  [7172] = {
    'Око Командования',
    nil,
    nil,
  },
  [7181] = {
    'Легенда о Корраке',
    {'Вторжение Грозовой Вершины – это не единственная угроза в этих землях, солдат. Война в долине ведется на два фронта. Тролли-канибалы из племени Секиры Зимы тоже представляют собой силу, с которой надо считаться.|n|nИх предводитель – Коррак Кровопуск – жестокая и коварная тварь.|n|nУбийство Коррака нанесло бы непоправимый удар племени Секиры Зимы. Убей его и получи награду!', },
    {'Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.|n|nЕсли Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.', },
  },
  [7201] = {
    'Последний элемент',
    {'У меня есть работа для тех, кто не боится заглянуть в глубины, $N. |n|nКлан Черного Железа научился создавать чрезвычайно мощных големов. |n|nИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. |n|nПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.', },
    {'Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.', },
  },
  [7202] = {
    'Коррак Кровопуск',
    {'Племя Секиры Зимы, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат.|n|nНичего, мы им покажем, как с нами связываться!|n|nНам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают! Его зовут Коррак Кровопуск.|n|nСмерть Коррака – это смерть всего племени Секиры Зимы! Убей его и возвращайся.', },
    {'Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.|n|nЕсли вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Мурпу в Альтеракские горы.', },
  },
  [7221] = {
    'Разговор с геологом Камнетеркой',
    {'А, $N, с докладом, да? Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь.|n|nПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.|n|nСмотри внимательно, когда будешь пробираться через Дун Болдар. Для |3-1($C), $Gкоторый:которая:c; не чурается работы, здесь найдется много дел.', },
    {'Поговорите с геологом Камнетеркой в гарнизоне Дун Болдара.', },
  },
  [7222] = {
    'Разговор с Воггой Смертобоем',
    {'$C? Отлично! Рады видеть тебя в Альтераке, $N. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!|n|nПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!|n|nВоггу можно найти в крепости Северного Волка.', },
    {'Поговорите с Воггой в крепости Северного Волка.', },
  },
  [7223] = {
    'Обломки брони',
    {'В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно.|n|nЕсли ты найдешь на поле боя обломки брони, приноси их мне, они нам пригодятся.', },
    {'Принесите 20 обломков брони Мурготу Подземной Кузне в Дун Болдар.', },
  },
  [7224] = {
    'Вражеский трофей',
    {'Если надешь на поле боя обломки вражеских доспехов, неси их мне. Из них выйдет отличная броня для наших собственных войск!', },
    {'Принесите 20 обломков брони кузнецу Регзару в деревню Северного Волка.', },
  },
  [7241] = {
    'Защита клана Северного Волка',
    {'Издалека доносится рокот барабанов войны, |3-6($C). Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна. |n|nСудя по твоему виду, можно решить, что ты $Gзакален в битвах и готов:закалена в битвах и готова; постоять за дело клана Северного Волка. |n|nА сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства. К северу от Мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину. Там тебе нужно отыскать воеводу Лаггронда.', },
    {'Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от деревни Мельница Таррен у подножия Альтеракских гор.', },
  },
  [7261] = {
    'Королевское право',
    {'Здесь, в Альтеракской долине, идут тяжелые бои. С одной стороны на нас наступают тролли-каннибалы из племени Секиры Зимы, с другой – дикари из клана Северного Волка. Во имя короля Магни Бронзоборода, все они должны быть уничтожены! Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!|n|nК сожалению, солдаты не растут на деревьях. Доложись лейтенанту Мурпу рядом с Альтеракской долиной и с честью приступай к несению службы в Грозовой Вершине!', },
    {'Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Мурпа рядом со входом в туннель и поговорите с ним.|n|nВо славу Бронзоборода!', },
  },
  [7281] = {
    'Братская любовь',
    {'Ужасно... В сражении я столкнулся со своим братом, командиром Грозовой Вершины.|n|nИз всех четырех командиров Грозовой Вершины он самый опасный. Возможно, Королева банши сможет возродить его после смерти, и тогда я докажу ему ошибочность его поступков...|n|nМой брат находится в глубине территории врага. Убей его и возвращайся ко мне. Я уверен, солдат, что у тебя хватит сил выполнить это задание.|n|nНо лучше не отправляйся в одиночку.', },
    {'Отправляйтесь на территорию Грозовой Вершины и убейте командира Карла Филипса. После выполнения задания возвращайтесь к командиру Луи Филипсу.', },
  },
  [7282] = {
    'Братская любовь',
    {'Нужно избавить его от страданий, солдат! Воистину, он не ведает, что творит. Ужасная Королева банши сделала его своей бездумной марионеткой.|n|nСтупай вперед, через Поле брани, в глубину территории Северного Волка. Найди моего брата и уничтожь его. Его мучениям должен прийти конец.', },
    {'Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.', },
  },
  [7301] = {
    'Свергнутые властители небес',
    {'Мы взяли их в плен, |3-6($R). Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. |n|nОбыщи западную Смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.', },
    {'Отправляйтесь в крепость Северного Волка и поищите командиров звена Макарча, Сквороца и Ромеона. Вернитесь с отчетом к командиру Даффи.', },
  },
  [7302] = {
    'Свергнутые властители небес',
    {'Наша воздушная поддержка в полном беспорядке, $N. Командиров звена сбили на вражеской территории. Ты $Gдолжен:должна; узнать, что с ними стало, чтобы мы могли попытаться их спасти! |n|nСмуггла в последний раз видели над укрытием Ледяного Крыла. Боевую виверну Мааши заметили у лесопилки Грозовой Вершины. Маэстр... кто-то видел, как этот пустоголовый идиот разбился возле северного оплота Дун Болдара. |n|nЭто вся информация, что у меня есть. За дело! Как следует прочеши указанные районы.', },
    {'Выясните, что стало с командирами звена Смугглом, Маашей и Маэстром. Вернитесь с отчетом к командиру Мулфорту.', },
  },
  [7321] = {
    'Нежный черепаховый суп',
    {'Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мертвых бы восстал, только бы скушать тарелочку! Хе-хе...|n|nКстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу.|n|nЕсли ты добудешь мне немного черепашьего мяса, я научу тебя варить такой суп!', },
    {'Принесите 10 кусков черепашьего мяса Кристофу Френчу на Мельницу Таррен.', },
  },
  [7341] = {
    'Честная сделка',
    nil,
    nil,
  },
  [7342] = {
    'Стрелы – для неженок!',
    nil,
    nil,
  },
  [7361] = {
    'Благосклонность клана Черного Копья',
    {'*Нажьяк ворчит.* |n|nПрежде чем появились ночные эльфы, были тролли. И именно от троллей пошли ночные эльфы. |n|nИх злобные вылазки против моего народа нельзя более терпеть. Олений Шлем хочет стереть нас с лица земли, чтобы не осталось и упоминания о тех, от кого ведут свой род он и его собратья. Не бывать этому! |n|nЗа каждого ночного эльфа, которого ты убьешь и обезглавишь, Надьяк будет одаривать тебя благосклонностью народа Черного Копья. Слава о твоих деяниях распространится по всему Калимдору и Восточным королевствам. Иди же и послужи Черному Копью!', },
    {'Вам поручили убивать в Альтеракской долине ночных эльфов.|n|nУбив ночного эльфа, вернитесь с его отрубленной головой к Нажьяку Проклятуну в крепость Северного Волка.', },
  },
  [7362] = {
    'Союзник тауренов',
    {'Мудрая Магата прислала меня в эту зону боевых действий, чтобы изучать другие расы. Точнее, мне поручено собрать образцы тканей гномов. Магату особенно интересует их живучесть. Ведь гномы – эти крошечные, жалкие создания, – проявляют удивительную устойчивость как к боевым ранениям, так и к обычным тяготам жизни.|n|nТебе повезло – мне как раз нужны помощники, чтобы выполнить поручение Магаты. Приноси мне пряди гномьих волос, и таурены будут считать тебя своим союзником.', },
    {'Убивайте гномов в Альтеракской долине.|n|nУбив гнома, принесите Раваку Зловещему Тотему в крепость Северного Волка пучок волос гнома.', },
  },
  [7363] = {
    'Человечья жизнь',
    {'Люди так отвратительны!|n|n*Командир Филипс брезгливо кривится.*|n|nКонечно, сейчас я состою на службе у клана Северного Волка, и все же я по-прежнему остаюсь слугой Сильваны.|n|nИ в свободное от службы время я подрабатываю, помогая Темным аптекарям Подгорода.|n|nМне поручено собирать осколки человеческих костей, которые будут использованы, чтобы исцелять людей от их жалкого состояния.|n|nЯ также могу давать аналогичное поручение своим подчиненным.|n|nИщите их. Убивайте их. И приносите мне осколки их костей!', },
    {'Вам поручили убивать людей в Альтеракской долине.|n|nУбив человека, принесите командору Луи Филипсу (который бродит между линией фронта и крепостью Северного Волка) осколок человеской кости.|n|nОкончить человеческие страдания совсем несложно!', },
  },
  [7364] = {
    'Награда Гномрегана',
    {'Сам главный механик прислал меня на это поле брани, чтобы защитить наших собратьев! До нас дошли вести, что таурены нарочно выискивают и убивают гномов! А самое ужасное, что они срезают с трупов павших их роскошные волосы! Этому необходимо положить конец. Мы обязаны отомстить!|n|nМы лишим их копыт, |3-6($C)! Принеси мне их копыта! Докажи, что ты – союзник гномов!', },
    {'Убивайте тауренов в Альтеракской долине.|n|nУбив таурена, вернитесь к Дирку Надувалло в Дун Болдар с копытом таурена.', },
  },
  [7365] = {
    'Реквием Оленьего Шлема',
    {'Олений Шлем отдал приказ: во время сражений всех троллей необходимо истребить. Они должны ответить за свое наглое заявление, что ночные эльфы ведут свой род от троллей.|n|nУничтожь троллей и принеси мне их амулеты. Повторяю: мне нужны их амулеты.', },
    {'Ваше задание – убивать в Альтеракской долине троллей.|n|nУбейте тролля и возвращайтесь к Атраманису в Дун Болдар с амулетом тролля из клана Черного Копья.', },
  },
  [7366] = {
    'Милосердие архиепископа',
    {'Доброта архиепископа сравнима только с его мудростью. Надо иметь невероятно чуткую душу, чтобы относиться к подобной швали с милосердием...|n|n*Командир Филипс в недоумении пожимает плечами.*|n|nОн слишком добр...Просто слишком.|n|nАрхиепископ просил нас, чтобы мы имели сострадание к нежити и даровали им быструю и верную смерть. Чтобы проявить подобное великодушие, мы должны раздобыть их черные, пораженные болезнью сердца.|n|nПринеси мне сердца Отрекшихся, чтобы мы могли сжечь их с надлежащими церемониями в Соборе Света. Поспеши, $N!', },
    {'Ваше задание – убивать в Альтеракской долине Отрекшихся.|n|nУбейте Отрекшегося и возвращайтесь к Карлу Филипсу (он ходит между лесопилкой и рудником) с сердцем Отрекшегося.', },
  },
  [7367] = {
    'Обезвредить угрозу',
    {'Клан Северного Волка позволил заманить себя в совершенно идиотскую ловушку, |3-6($C). Надо быть более осмотрительным, действуя на территории врага.|n|nЕсли хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает их за минные поля, – я говорю об эксперте по взрывчатым веществам. Пока он жив, минные поля существуют. Но если он будет мертв, поддерживать их станет некому.|n|nНе исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови. Удачи тебе!', },
    {'Найдите эксперта по взрывчатым веществам из клана Северного Волка и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Грозовой Вершины.', },
  },
  [7368] = {
    'Обезвредить угрозу',
    {'Про противопехотные мины я знаю все. Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта.|n|nЕсли ты хочешь обезвредить все минные поля Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам. Этот трусливый дворф скорее всего прячется в первой башне Поля брани. Убей его, и минные поля будут обезврежены раз и навсегда.|n|nКак убьешь его, возвращайся ко мне. Добрые дела не должны оставаться без награды.', },
    {'Найдите эксперта по взрывчатым веществам из клана Грозовой Вершины и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Северного Волка.', },
  },
  [7381] = {
    'Возвращение Коррака',
    {'Коррак мертв, но надолго ли? О магии троллей ходит грозная слава. Я не удивлюсь, если их мертвый вождь снова восстанет, чтобы править своим племенем.|n|nТы знаешь, что делать, если это случится.|n|n*Воевода Лаггронд проводит ребром ладони по горлу.*|n|nНо на этот раз принеси его череп. И гляди в оба, солдат!|n|n$GСвободен:Свободна;!', },
    {'В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.|n|nПринесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.', },
  },
  [7382] = {
    'Коррак Бессмертный',
    {'Что-то здесь не так... Кто-нибудь догадался сжечь тело Коррака? Эти синекожие язычники ни перед чем не остановятся, чтобы возродить своего вождя.|n|nСмотри в оба, $N. Не удивляйся, если снова увидишь Коррака в живых. Убей его снова, но на этот раз обязательно сожги тело.|n|nЧтобы уж все проделать наверняка, отрежь ему голову и принеси череп мне, а все остальное пусть горит синим пламенем.', },
    {'В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.|n|nПринесите череп Коррака лейтенанту Мурпу в предгорья Хилсбрада.', },
  },
  [7383] = {
    'Венец Земли',
    {'Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.|n|nНо пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-востоку от Врат Дарнаса. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.', },
    {'Наполните аметистовый фиал и принесит его Коритрасу Лунному Гневу в Доланаар.', },
  },
  [7385] = {
    'Галлон крови',
    nil,
    nil,
  },
  [7386] = {
    'Гроздь кристаллов',
    nil,
    nil,
  },
  [7401] = {
    'Разыскиваются: ДВОРФЫ!',
    {'Согласно приказу сержанта Язры Кровавый Рык, все дворфы на поле сражения подлежат неукоснительному уничтожению.|n|nПосле боя из каждого убитого дворфа следует выдрать хребет, а тело оставить вонять и разлагаться, – в назидание всем, кто осмелится замахнуться на Орду.|n|nВыдранные хребты, как доказательство своих подвигов, сдавайте Язре Кровавый Рык.', },
    {'Ваша задача – убивать дворфов в Альтеракской долине.|n|nУбейте дворфа и вырвите ему хребет. Отнесите хребет дворфа сержанту Язре Кровавый Рык в крепость Северного Волка.', },
  },
  [7402] = {
    'Разыскиваются: ОРКИ!',
    {'Согласно приказу капрала Норга Грозовой Вершины, все солдаты Грозовой Вершины должны убить как можно больше орков.|n|nВ качестве трофея предъявляйте орочьи зубы.|n|nПеред тем, как вырывать оркам зубы, не забывайте надевать защитные перчатки!', },
    {'Ваше задание – убивать орков в Альтеракской долине.|n|nУбейте орка и доставьте зуб орка капралу Норгу Грозовой Вершине в Дун Болдар.', },
  },
  [7421] = {
    'Защита Черного Копья',
    nil,
    nil,
  },
  [7422] = {
    'Хоть шерсти клок...',
    nil,
    nil,
  },
  [7423] = {
    'Костяная лихорадка',
    nil,
    nil,
  },
  [7424] = {
    'Какое такое копыто?',
    {'Я хочу опробовать свой портативный крошшер не меньше тебя, |3-6($R), но для того, чтобы его сделать, мне нужны материалы – много материалов!|n|nСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый крошшер. Их можно достать на лесопилке.|n|nДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.', },
    nil,
  },
  [7425] = {
    'Амулеты для Оленьего Шлема',
    nil,
    nil,
  },
  [7426] = {
    'Любовь к ближнему',
    nil,
    nil,
  },
  [7427] = {
    'Разыскивается: БОЛЬШЕ ДВОРФОВ!',
    nil,
    nil,
  },
  [7428] = {
    'Разыскивается: БОЛЬШЕ ОРКОВ!',
    nil,
    nil,
  },
  [7429] = {
    'Освободите Нотта!',
    nil,
    nil,
  },
  [7441] = {
    'Пузиллин и старейшина Аж\'Тордин',
    {'Представь себе, $Gчужестранец:чужестранка;: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре\'Таласа!|n|nКлюч мне теперь ни к чему: я обменял свое бессмертие на свободу, – но книга мне нужна позарез!|n|nОтыщи мне этого беса Пузиллина, и добудь у него книгу!|n|nИщи его в Квартале Криводревов Забытого Города.', },
    {'Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж\'Тордина.|n|nЕсли добудете книгу, вернитесь к Аж\'Тордину в павильон Лорисс в Фераласе.', },
  },
  [7461] = {
    'Древнее безумие',
    {'Ну что, довольно ли ты $Gслышал:слышала;? Надеюсь, ты не устрашишься вступить в бой?|n|nЭтому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер\'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!', },
    {'Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер\'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер\'тера, рассеется.|n|nВойдите в Тюрьму Бессмер\'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.|n|nЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен\'дралар.', },
  },
  [7462] = {
    'Сокровище Шен\'дралар',
    {'В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.', },
    {'Вернитесь в Читальню и найдите сокровище Шен\'дралар. Получите свою награду!', },
  },
  [7463] = {
    'Магический напиток',
    {'А-а, |3-6($R), $Gпосвятивший:посвятившая:r;себя магии! Удивительно. Я не видывал подобных тебе уже... сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот!|n|nУ меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придется выполнить одно мое поручение.|n|n*Лидрос хихикает.*|n|nВ Эльдре\'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его... того... занести в каталог.|n|nСтупай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси ее мне, а я тебя научу одной полезной штучке!', },
    {'Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.', },
  },
  [7481] = {
    'Эльфийские легенды',
    {'Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разоренной родной земли, унеся с собой несколько древних эльфийских артефактов.|n|nПоиски пропавшего мастера привели нас из руин Кель\'Таласа через Пылающие степи и морские просторы в Фералас.|n|nМы подозреваем, что эльф искал убежища в залах Эльдре\'Таласа (ныне известного как Забытый Город).|n|nОтыщи его, $Gстранник:странница;! Жив он или мертв, а знания, которые он унес с собой, отыскать необходимо!', },
    {'Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.', },
  },
  [7482] = {
    'Эльфийские легенды',
    {'Несколько лет тому назад одинокий эльфийский мастер по имени Кариэль Винтхалус бежал из своей разоренной родной земли, унеся с собой несколько древних эльфийских артефактов.|n|nПоиски пропавшего мастера привели нас из руин Кель\'Таласа через Пылающие степи и морские просторы в Фералас.|n|nМы подозреваем, что эльф искал убежища в залах Эльдре\'Таласа (ныне известного как Забытый Город).|n|nОтыщи его, $Gстранник:странница;! Жив он или мертв, а знания, которые он унес с собой, отыскать необходимо!', },
    {'Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к книжнице Рунический Шип и сообщите ей все, что вам удалось узнать.', },
  },
  [7483] = {
    'Манускрипт скорости',
    {'Мастер Винтхалус потерял "Манускрипт Скорости" в восточном крыле. Этот манускрипт позволит тебе наложить на все свое снаряжение небольшое ускоряющее заклятие. Детские игрушки, на самом деле…|n|nТем не менее, если тебя это все же интересует, принеси мне манускрипт, и кое-какие необходимые реагенты.|n|nХм... Насколько я помню, там требуется кровь героев, безупречный черный алмаз и большие сверкающие осколки. Впрочем, я могу и ошибиться!|n|n*Лидрос пожимает плечами.*', },
    {'Принесите сказителю Лидросу в Забытом Городе "Манускрипт Скорости", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 2 образца крови героев, чтобы получить магический знак стремительности.', },
  },
  [7484] = {
    'Манускрипт средоточия',
    {'Этот манускрипт едва не вызвал интерес у одного из юных фамильяров хранителя мудрости! Бедняжка, ему было всего несколько недель от роду!|n|nТем из вас, кто интересуется магией, этот манускрипт может пригодиться!|n|nОн пропал где-то в этом крыле. Могу только предположить, что его прибрал к рукам один из духов высокорожденных.|n|nПринесите мне "Манускрипт Средоточия", несколько больших сверкающих осколков, шкуру тени и безупречный черный алмаз, и я создам для вас магический знак.', },
    {'Принесите сказителю Лидросу в Забытом Городе "Манускрипт Средоточия", 1 безупречный черный алмаз, 4 больших сверкающих осколка и 2 образца шкуры тени, чтобы получить магический знак сосредоточения.', },
  },
  [7485] = {
    'Манускрипт защиты',
    {'Потеряв этот манускрипт, он рыдал, как ребенок! Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний? Абсурд! Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей.|n|nПринеси мне этот манускрипт вместе с безупречным черным алмазом, большими сверкающими осколками и истлевшей шовной нитью поганища, и я воссоздам этот магический знак!|n|nАх, да: в общем, ищи в северном крыле.', },
    {'Принесите сказителю Лидросу в Забытом Городе "Манускрипт Защиты", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 1 истлевшую шовную нить поганища, чтобы получить магический знак защиты.', },
  },
  [7486] = {
    'Награда для героя',
    {'$N, твои заслуги перед Повелителями Вод превосходят самые смелые ожидания. Мы не могли предположить, что обитатель этого мира может обладать подобной силой!|n|nНе знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду.|n|nОтправляйся в южную часть острова и найди сундук, сокрытый в волнах. В том сундуке твоя награда.|n|nИди, $N. Забери свою награду.', },
    {'Заберите свою награду из сундука Гидраксиса.', },
  },
  [7487] = {
    'Сродство с недрами',
    {'Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($R). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.|n|n$GУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...|n|nУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.|n|nСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.', },
    {'Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.', },
  },
  [7488] = {
    'Сеть Лефтендрис',
    {'Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь ее извращенной приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Летендрис не остановить, она нанесет непоправимый урон нашему миру!|n|nОстанови ее, $N. Отыщи ее и отними у нее эту сеть. Она, скорее всего, где-то неподалеку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу...', },
    {'Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.', },
  },
  [7489] = {
    'Сеть Лефтендрис',
    {'Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала все новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать ее против своих врагов!|n|nЛефтендрис необходимо остановить. Отыщи ее в Квартале Криводревов в Забытом Городе, повергни ее и принеси ее сеть мне, чтобы мы могли передать ее для изучения более здравомыслящим эльфам крови.', },
    {'Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.', },
  },
  [7490] = {
    'Победа Орды',
    {'Тебе удалось совершить невозможное! Царица черных драконов лежит мертвой у твоих ног. Отруби ей голову и отнеси ее своему вождю.', },
    {'Отнесите голову Ониксии Траллу в Оргриммар.', },
  },
  [7491] = {
    'На виду у всех',
    {'Властитель Рунтак ожидает тебя в Аллее Силы.|n|n<Тралл отдает вам честь.>|n|nНе заставляй его ждать, герой!', },
    {'Найдите властителя Рунтака в Аллее Силы.', },
  },
  [7492] = {
    'Лагерь Мохаче',
    {'Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи. Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!|n|nПослужи Орде, $N. Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало.', },
    {'Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе.', },
  },
  [7493] = {
    'Все еще только начинается!',
    nil,
    nil,
  },
  [7494] = {
    'Крепость Оперенной Луны',
    {'$N! Твоя помощь нужна в Фераласе!|n|nЛефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре\'Таласа, ныне именуемого Забытым Городом. Есть основания предполагать, что у нее с собой мощный магический артефакт, который необходимо вернуть.|n|nЛатроникус Лунное Копье ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт.|n|nПослужи Альянсу! Отправляйся к Латроникусу. Он находится в Крепости Оперенной Луны в Фераласе.', },
    {'Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе.', },
  },
  [7495] = {
    'Славная победа Альянса',
    {'Вы совершили невозможное. Царица черных драконов лежит мертвой у ваших ног. Возьмите ее голову и передайте ее королю Вариану Ринну.', },
    {'Отнесите голову Ониксии королю Вариану Ринну в Штормград.', },
  },
  [7496] = {
    'Праздник добрых времен',
    {'$N, найди майора Маттингли в Аллее Героев. Он будет тебя ждать...', },
    {'Найдите майора Маттингли в Аллее Героев.', },
  },
  [7497] = {
    'Все еще только начинается!',
    nil,
    nil,
  },
  [7498] = {
    'Гарона: Исследование скрытности и предательства',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7499] = {
    'Кодекс Защиты',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7500] = {
    'Поваренная книга чародея',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7501] = {
    'Свет и как его раскачать',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7502] = {
    'Укрощая тени',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7503] = {
    'Величайшая гонка охотников',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7504] = {
    'Святая Болонья: О чем не говорит свет',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7505] = {
    '"Ледяной шок и вы"',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7506] = {
    'Изумрудный Сон',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
  [7507] = {
    'Справочник Форора',
    {'Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше.|n|nТакое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажен и читается с трудом.', },
    {'Верните "Справочник Форора по убийству драконов" в Читальню.', },
  },
  [7508] = {
    'Ковка Кель\'Серрара',
    {'Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу.', },
    {'Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.', },
  },
  [7509] = {
    'Ковка Кель\'Серрара',
    {'Отнеси потускневший древний клинок в логово Ониксии и вызови драконицу на бой.|n|nВозможно, тебе придется прибегнуть к кое-каким уловкам, чтобы заставить ее раскалить меч. Разумеется, в бою она будет пытаться испепелить тебя своим огненным дыханием. Положи потускневший древний клинок где-нибудь поблизости и постарайся, чтобы огненное дыхание попало на клинок. А после этого – если, конечно, выживешь, – схвати раскаленный клинок и прикончи драконицу.|n|nВонзи горячий древний клинок в ее тело, чтобы получить закаленный древний клинок.', },
    {'Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!|n|nПоследнее, что нужно сделать – это убить драконицу и вонзить раскаленный древний клинок в ее труп.|n|nСделайте это – и Кель\'Серрар навеки станет вашим!', },
  },
  [7521] = {
    'Громораан Искатель Ветра',
    {'Я рассказал тебе все, что знаю, $N. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя огня.|n|nЕсли ты справишься, с тобой пребудет благословение Громораана.', },
    {'Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правый и левый наручник Ветроносца, 10 слитков элементия и сущность Повелителя Огня верховному лорду Демитриану.', },
  },
  [7522] = {
    'Сосуд Возрождения',
    {'Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!', },
    {'Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.', },
  },
  [7541] = {
    'Служба Орде',
    nil,
    nil,
  },
  [7562] = {
    'Мор\'зул Вестник Крови',
    {'Ты хорошо $Gизучил:изучила; темные искусства и $Gобрел:обрела; такую власть над существам из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели.|n|nВызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор\'зулом Вестником Крови. Он разбил лагерь рядом с Алтарем Бурь в Пылающих степях.|n|nСтупай, $N. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей.', },
    {'Поговорите с Мор\'зулом Вестником Крови у Алтаря Бурь в Пылающих степях.', },
  },
  [7563] = {
    'Ярость крови',
    {'Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила.|n|nВ далеких Зимних Ключах живут зверосовы. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шепота лишило их разума, и они бродят по снегам в полном безумии.|n|nИз их крови я и сделаю чернила. Остается ее добыть.', },
    {'Принесите 30 бутылок крови яростных зверей Мор\'зулу Вестнику Крови в Пылающие степи.', },
  },
  [7564] = {
    'Дикоглаз',
    {'Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесенную тобой кровь; отнеси ее Горзиеки, пусть приступает к работе.', },
    {'Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях.', },
  },
  [7581] = {
    'Тюремные кандалы',
    {'Ты $Gдолжден:должна; добыть у младших демонов кандалы для стражника ужаса.|n|nКровь сатира из племени Буйного Нрава, что живут в Забытом Городе, для этого сгодится. Свернувшаяся кровь скрепит осколки Хедерины и даст силу хрустальной темнице.', },
    {'Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.', },
  },
  [7582] = {
    'Тюремная камера',
    {'Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы. Они известны как слезы Хедерины.|n|nДаже чудовищная сила стражника ужаса не сможет разбить стены тюрьмы, сделанной из этого материала.|n|nОтправляйся в Теснину Зловещего Шепота в Зимних ключах, и добудь этих слез.', },
    {'Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.', },
  },
  [7583] = {
    'Заточение',
    {'Темница готова. Теперь самое трудное дело.|n|nТы $Gдолжен:должна; найти и схватить командира стражников ужаса в Гниющем шраме при помощи этой хрустальной темницы.|n|nОсторожнее! Стражник ужаса -коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнешь обряд заточения. Он будет отчаянно отбиваться, пытаясь избежать плена.|n|nОн будет смотреть только на тебя, $N. Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!', },
    {'Отправляйтесь в Гниющий шрам и и найдите командира стражников ужаса.|n|nПри помощи светящегося кристалла заточения поймайте командира стражников ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения.|n|nЕсли вы добьетесь успеха, отнесите пленного стражника ужаса Дайо в Гниющий шрам.', },
  },
  [7601] = {
    'Что хочет Ниби',
    {'Если хочешь научиться у меня призывать инфернала-слугу, ты $Gдолжен:должна; убить Крошиуса и добыть из его пылающих останков огненное ядро. Но это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придется снова воспламенить его тело и поднять его из праха. Но для этого тебе придется добыть другие ингредиенты из других демонических сущностей.|n|nМой бес по имени Бесенок покажет тебе дорогу.', },
    {'Поговорите с Бесенком в Оскверненном лесу.', },
  },
  [7602] = {
    'Безупречная субстанция Скверны',
    {'Если ты намереваешлся воскресить Крошиуса, тебе понадобится пламя Скверны. Я могу зажечь его, но для этого потребуются кое-какие ингредиенты.|n|nТебе придется принести мне безупречной субстанции Скверны из трех краев нашего мира.|n|nПервый тип субстанции ты найдешь у сатиров из племени Легаши, что в Азшаре. Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях.|n|nПринеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса.', },
    {'Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.|n|nБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.|n|nДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.', },
  },
  [7603] = {
    'Огненное ядро Крошиуса',
    {'Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран. Возьми этот пламень Скверны и воспламени его останки. Пламя оживит павшего инфернала.|n|nПосле этого он наверняка пришибет и тебя, и твоего приспешника.|n|nЕсли каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби.', },
    {'Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.|n|nПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.', },
  },
  [7604] = {
    'Заключение договора',
    {'$GНижеподписавшийся:Нижеподписавшаяся; со всей ответственностью подтверждает, что сульфуронский слиток, переданный $Gим:ею; братству Тория (ООО "БТ"), является подлинником. $GНижеподписавшийся:Нижеподписавшаяся; также подтверждает, что ООО "БТ" не несет никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу.|n|nПодпись под договором автоматически означает согласие $Gподписавшегося:подписавшейся; со всеми условиями, перечисленными в документе.|n|n_______________|n|nПодпись', },
    {'Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.', },
  },
  [7621] = {
    'Предупреждение',
    nil,
    nil,
  },
  [7622] = {
    'Баланс Света и Тени',
    {'Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма.|n|nОни выйдут на свет, и ты $Gдолжен:должна; защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование.|n|nЭто настоящее испытание для всех твоих способностей. Да поможет тебе Свет, $N.', },
    {'Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнении задания.|n|nЧисло погибших крестьян можно узнать, посмотрев на Колья Смерти.', },
  },
  [7623] = {
    'Лорд Гиблопуст',
    {'Морзул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звездной пыли. А ее нелегко найти в Азероте!|n|nОна может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звездной пылью.|n|nВпрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недешевы...', },
    {'Купите зелья Теней у Горзиеки в Алтаре Бурь, что Пылающих степях.|n|nПриняв зелья, пройдите через Джеденар в Оскверненном лесу и поговорите с лордом Гиблопустом, который находится в Оплоте Теней.', },
  },
  [7624] = {
    'Улатек Предатель',
    {'Хочешь заслужить мою милость? Что ж, тогда убей, кого я укажу.|n|nМой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел\'нуратом из Зорота. Хел\'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион...|n|nДокажи, что служишь мне, а не моим противникам. Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе. Передай ему, что мне известна его тайна. Вот увидишь, он затрясется от страха. Принеси мне сердце предателя!', },
    {'Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.', },
  },
  [7625] = {
    'Зоротианская звездная пыль',
    {'Так ты $Gявился:явилась; в поисках зоротианской звездной пыли? Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата? Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?|n|nОтлично. У моего слуги, Ур\'Дана, есть большой запас зоротианской звездной пыли. Обращайся к нему... если денег хватит.', },
    {'Купите зоротианскую звездную пыль у Ур\'Дана из Оплота Теней в Джеденаре, что в Оскверненном лесу. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.', },
  },
  [7626] = {
    'Колокол Детмуры',
    {'Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трех предметов, необходимых для создания круга Великого призыва. Сопряженный с Колесом и Свечой, он предоставит в твое распоряжение огромный запас магической энергии.|n|nМой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки.', },
    {'Отнесите 2 эликсира энергии Тьмы Горзиеки Дикоглазу в Пылающие степи.', },
  },
  [7627] = {
    'Колесо Черного Похода',
    {'Колесо Черного Похода содержит в себе и направляет черную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда черного железа, которую может добыть опытный горняк.|n|nПринеси моему слуге все необходимое.', },
    {'Отнесите 6 больших сверкающих осколков и 25 кусков руды черного железа Дикоглазу в Пылающие степи.', },
  },
  [7628] = {
    'Свеча Судного дня',
    {'Свеча Судного дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжешь всех упрямых демонов!|n|nВпрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя черного дракона. Купи ее у мастера снятия шкур и принеси Горзиеки Дикоглазу.', },
    {'Принесите 3 чешуи черного дракона Горзиеки Дикоглазу в Пылающие степи.', },
  },
  [7629] = {
    'Доставка беса',
    {'Для подготовки пергамента Морзула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!|n|nВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.|n|nЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.', },
    {'Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.', },
  },
  [7630] = {
    'Арканит',
    {'Итак, Колокол, Колесо и Свеча готовы. Осталось создать черный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут.|n|nДля создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика.|n|nПринеси мне арканит, и я создам черный магнит.', },
    {'Принесите 1 арканитовый слиток Горзиеки в Пылающие степи.', },
  },
  [7631] = {
    'Зоротианский конь погибели',
    {'Все готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звездной пылью... И отрыть портал в Зорот.|n|nВсе инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать все в точности так, как написано, или успеха не добиться.|n|nУдачи, $N. И да попадут души твоих врагов в твой мешочек осколков.', },
    {'Прочтите инструкции Мор\'зула. Призовите зоротианского коня погибели, одолейте его и подчините его дух.', },
  },
  [7632] = {
    'Древний лист',
    {'Кожица листа светится ярко-зеленым. Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки.|n|nЕсли задуматься, то этот лист – наверняка нечто очень древнее и могущественное.|n|nМожет, поискать, кому он принадлежит?', },
    {'Найдите хозяина древнего окаменелого древесного листа. Удачи, $N, мир велик.', },
  },
  [7633] = {
    'Посвящение',
    nil,
    nil,
  },
  [7634] = {
    'Перетянутый жилами лист древня',
    {'Привествую тебя, |3-6($C). Я Хастат, древо мудрости. Я храню память тысячелетий.|n|nЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.|n|nПринеси мне жил взрослого синего дракона, и получишь колчан.', },
    {'Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.', },
  },
  [7635] = {
    'Подходящая тетива',
    {'Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.|n|nЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.', },
    {'Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.', },
  },
  [7636] = {
    'Ветвь ходячего Древа',
    {'Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, |3-6($C). Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.|n|nТы $Gдолжен:должна; выследить этих демонических разносчиков порчи, $N. Помни – ты $Gдолжен:должна; лично разобраться с ними – иначе сбегут. Пока ты $Gодин:одна;, они будут пытаться уничтожить тебя. Ты $Gдолжен:должна; сразить их, обратить их надменность в ничтожество!|n|nЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.', },
    {'Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:|n|nСимон Совратительницу.|n|nКлинфрана Безумного.|n|nСоленора Убийцу.|n|nАрториуса Судьбоносного.|n|nУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.|n|nВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.|n|nВы ОБЯЗАНЫ выполнить это задание в одиночку.', },
  },
  [7637] = {
    'Жертва необходима',
    {'Чтобы подготовиться к этому заданию, ты $Gдолжен:должна; сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.|n|nДля выполнения задания ты $Gдолжен:должна; получить курильницу экзорцизма у Верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.|n|nОтправляйся в Стальгорн и поговори с Верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.|n|nА теперь иди, $N, время терять нельзя.', },
    {'Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.', },
  },
  [7638] = {
    'Лорд Грейсон Тенелом',
    {'Пришло твое время, $N, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.|n|nПоговори с лордом Грейсоном Тенеломом здесь, в Храмовом квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.|n|nЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, $Gмой благородный брат:моя благородная сестра;!', },
    {'Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.', },
  },
  [7639] = {
    'Демонстрация истинного правосудия',
    {'Прими эту курильницу и будь $Gблагословен:благословенна;. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.|n|nНыне возвращайся к лорду Грейсону Тенелому в Штормград, $N. Он даст тебе поручение.', },
    {'Принесите курильницу экзорцизма лорду Грейсону Тенелому в Храмовый квартал Штормграда.', },
  },
  [7640] = {
    'Изгнание призраков из Долины Ужаса',
    {'Я добавил в курильницу щепотку зараженной земли Долины Ужаса, что в Восточных Чумных землях. Ты $Gдолжен:должна; будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зеленое свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов.|n|nКогда свершишь суд над призраками, я поставлю перед тобой новую задачу.', },
    {'Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Храмовый квартал Штормграда.', },
  },
  [7641] = {
    'Работа Гриманда Элмора',
    {'Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он еще был в достаточной мере настроен на призрачный мир.|n|nНо все по порядку, $N – сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор. Он берет за свою работу недешево, но качество его работы – как раз то, что нам нужно. Поговори с ним.', },
    {'Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.', },
  },
  [7642] = {
    'Сбор необходимого',
    {'Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять... если считать золото для меня. Эта плата – за весь мой труд, а также седло и стремена ручной работы.|n|nКогда наберешь все это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе.', },
    {'Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет.', },
  },
  [7643] = {
    'Дух древнего коня',
    {'Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, $N.|n|nТолько имей в виду, что просто освободить – недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдешь его в Южнобережье, если поговоришь с Меридет Карлсон.', },
    {'Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.|n|nУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.', },
  },
  [7644] = {
    'Благословенный арканитовый чепрак',
    {'После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться. На миг кажется, будто все вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня. Теперь он в вашем заплечном мешке.|n|nОчевидно, чепрак получил благословение. Теперь, согласно наставлениям лорда Победителя Тени, вам следует вернуться с этим чепраком к нему в Штормград.', },
    {'Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Храмовый квартал Штормграда.', },
  },
  [7645] = {
    'Сытный манный лошадиный корм',
    {'Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться!|n|nЯ сделаю, что тебе надо, ПАЛАДИН... ЗАЩИТНИК, тоже мне... Но обойдется это недешево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесенные страдания!|n|nПосмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН.', },
    {'Принесите 20 cытных манных печений – ключевых составляющих сытного манного лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продается печенье только в Серебряном Рассвете.|n|nКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.', },
  },
  [7646] = {
    'Магический кристалл',
    {'Теперь мы должны сконструировать магический кристалл – так начнется твой подвиг и освобождение плененного духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты $Gиспользовал:использовала;, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора.|n|nДа, и еще нужны последние два компонента – азеротский алмаз и безупречный черный алмаз. Эти два камня станут маяком, пронзающим тьму!', },
    {'Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда.', },
  },
  [7647] = {
    'Суд и расплата',
    {'Возьми эту суму – в ней собраны предметы, которые понадобятся тебе для выполнения задания.|n|nИспользуй магический кристалл в самом сердце подвала Главного склепа для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, $N, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна.|n|nЖелаю удачи!', },
    {'Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.|n|nВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.', },
  },
  [7648] = {
    'Шедевр Гриманда',
    {'*Гриманд утирает пот со лба, сияя от гордости.*|n|nГотово, $Gдруг мой:моя леди;. Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Победителя Тени, когда он отправлялся за своим конем. Благодарю тебя за доверие.|n|nНесомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела.', },
    {'Покажите арканитовый чепрак лорду Грейсону Тенелому в Храмовом квартале Штормграда.', },
  },
  [7649] = {
    '"Зачарованная ториевая броня", том I',
    {'Том помечен печатью Читальни.', },
    {'Верните книгу законным владельцам.', },
  },
