  [7937] = {
    'Ты найдешь свою удачу...',
    {'"Ты найдешь свою удачу в Восточной долине".|n|nЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Лесопилку Восточной долины в Элвиннском лесу. Возле стойл стоит копна сена... На этом видение обрывается.', },
    {'Отыщите свою удачу на Лесопилке Восточной долины в Элвиннском лесу.', },
  },
  [7938] = {
    'Ты найдешь свою удачу...',
    {'"Ты найдешь свою удачу в Мертвых копях".|n|nЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Мертвые копи возле разрушенной деревни Луноречье в Западном Крае. Запутанные ходы приводят вас к порталу, который ведет в самое сердце шахт. Вдруг перед порталом возникает странный сундук... На этом видение обрывается.', },
    {'Отыскать свою удачу в Мертвых копях в Западном Крае.', },
  },
  [7939] = {
