  [7944] = {
    'Ты найдешь свою удачу...',
    {'"Ты найдешь свою удачу в Пещерах Стенаний."|n|nЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите пещеру, расположенную к юго-западу от Перекрестка в Степях. Запутанные ходы приводят вас к порталу, который ведет в самое сердце пещеры. Вдруг перед порталом возникает странный сундук. На этом видение обрывается.', },
    {'Отыскать свою удачу в Пещерах Стенаний в Степях.', },
  },
  [7945] = {
    'Ты найдешь свою удачу...',
    {'"Ты найдешь свою удачу возле утеса Бледногривов".|n|nЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите утес Бледногривов в Мулгоре. Возле входа в пещеру стоит пень... На этом видение обрывается.', },
    {'Отыскать свою удачу возле утеса Бледногривов в Мулгоре.', },
  },
