  [8269] = {
    'Ленты жертвоприношения',
    nil,
    nil,
  },
  [8271] = {
    'Герой Грозовой Вершины',
    nil,
    nil,
  },
  [8272] = {
    'Герой Северного Волка',
    nil,
    nil,
  },
  [8273] = {
    'Благодарность Оран',
    nil,
    nil,
  },
  [8275] = {
    'Отвоевание Силитуса',
    {'Внемлите, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.|n|nСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!|n|nВсе на защиту Азерота! Все способные держать оружие должны пройти инструктаж у призывательницы ветров Гордого Рога в Крепости Кенария!', },
    {'Поговорите с призывательницей ветров Гордым Рогом в Крепости Кенария.', },
  },
  [8276] = {
    'Отвоевание Силитуса',
    {'Внемлите, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.|n|nСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!|n|nВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордыму Рогу в Крепости Кенария! Да сгинут силитиды!', },
    {'Поговорите с призывательницей ветров Гордым Рогом в Крепости Кенария.', },
  },
  [8277] = {
    'Смертельный яд',
    {'Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из Крепости Кенария редкие травы. Точее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.|n|nЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.|n|nНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстролапов. Принеси мне несколько жал и клыков, и я сделаю противоядие.', },
    {'Принесите Битиссе Шаткобрус из Крепости Кенария 8 жал камнехвостых скорпидов и 8 клыков песчаных пауков-быстролапов.', },
  },
  [8278] = {
    'Последняя надежда Ноггла',
    {'Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.|n|nПридется попросить тебя отправиться за образцами, $N. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.', },
    {'Принесите Битиссе Шаткобрус из Крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.', },
  },
  [8279] = {
    'Сумеречный словарь',
    {'Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги – мои друзья!|n|nЧтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три ее главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота.', },
    {'Принесите три главы Сумеречного словаря отшельнику Ортеллу из Силитуса.', },
  },
  [8280] = {
    'Надежные поставки',
    {'Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем ее, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно.|n|nПесчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки.', },
    {'Убейте 15 землечерпов по поручению призывательницы ветров Гордого Рога.', },
  },
  [8281] = {
    'Обеспечение безопасности',
    {'Ты великолепно себя $Gзарекомендовал:зарекомендовала;, $N. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители.|n|nЧтобы приструнить этих червяков, придется убить их побольше. Но мы не можем подвергать опасности наше снабжение.', },
    {'Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордого Рога.', },
  },
  [8282] = {
    'Потерянная сумка Ноггла',
    {'Где я? Где моя сумка? *вздыхает* Наверное, я потерял ее, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрел прямо в гнездо камнехвостых живодеров.|n|nВ моей сумке были ценнейшие реагенты. Без них мы с Битикс не сможем делать зелья для Крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей.|n|nНа Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода.', },
    {'Принесите сумку Ноггла из гор в южной части Силитуса и верните ее хозяину в Крепости Кенария.', },
  },
  [8283] = {
    'РОЗЫСК: Смертехват, гроза пустыни',
    {'Согласно последним сведениям, ужасный скорпион, Смертехват, отступил в южные горы перед лицом нашествия силитидов. Эта тварь представляет большую угрозу патрулям и экспедициям южных регионов. Тех, кто поспособствует ее уничтожению, будет ждать неплохая награда. По вопросам получения награды обращаться к капитану Вишу Коцусу, на вершину сторожевой башни Крепости Кенария.', },
    {'Принесите хелицеры Смертехвата Вишу Коцусу, капитану стражи.', },
  },
  [8284] = {
    'Сумеречная тайна',
    {'На северо-западе отсюда некогда благоденствовал лагерь служителей культа Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали.|n|nМне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе.', },
    {'Геолог Ехидная из Крепости Кенария просит вас собрать 8 фрагментов Сумеречной таблички.', },
  },
  [8285] = {
    'Дезертир',
    {'Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живет в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички.|n|nВозьми восстановленную табличку и отнеси ее Ортеллу.', },
    {'Отнесите восстановленную табличку отшельнику Ортеллу в Силитус.', },
  },
  [8286] = {
    'Что ждет нас завтра',
    {'Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на мое искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны.|n|n"Навеки останешься ты, коли так нужно," – сказал он, и с этими словами сделал меня Стражем.|n|nТолько взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать.', },
    {'Отправляйтесь в Пещеры Времени в Танарисе и найдите Анахроноса, из рода Ноздорму.', },
  },
  [8287] = {
    'Ужасная цель',
    {'Ну вот... Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краев Сумеречный Молот, верно? Это поспособствует воплощению их планов.|n|nОтнеси этот пергамент их главе, командиру Мар\'алиту. Скоро Сумеречный Молоты изгонят из этих земель и их жадные ручки до меня не дотянутся!', },
    {'Отнесите переписанный с таблички расшифрованный текст командиру Мар\'алиту.', },
  },
  [8288] = {
    'Кто будет избран?',
    {'Время у нас на исходе! Нам необходим герой! Выполнить мое задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Племени.|n|nВ логове повелителя Черной горы живет жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Зал Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне ее голову. Это будет первым шагом на твоем пути.', },
    {'Принесите голову предводителя драконов Разящего Бича Баристольфу из Зыбучих Песков в Крепость Кенария в Силитусе.', },
  },
  [8289] = {
    'Талисманы заслуг',
    nil,
    nil,
  },
  [8290] = {
    'Долой захватчиков!',
    {'$GЮный:Юная:c; |3-6($C)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!|n|nОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!|n|nНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', },
    {'Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальной Песне в рощу Среброкрылых.', },
  },
  [8291] = {
    'Долой захватчиков!',
    {'$GЮный:Юная:c; |3-6($C)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!|n|nОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!|n|nНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $N, и получишь награду!', },
    {'Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальной Песне в рощу Среброкрылых.', },
  },
  [8292] = {
    'Талисманы заслуг',
    nil,
    nil,
  },
  [8293] = {
    'Почетный знак',
    nil,
    nil,
  },
  [8294] = {
    'Громи захватчиков-Среброкрылых!',
    {'Чащобы Ясеневого леса падут пред мощью Орды, |3-6($R)! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?|n|nПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', },
    {'Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', },
  },
  [8295] = {
    'Громи захватчиков-Среброкрылых!',
    {'Чащобы Ясеневого леса падут пред мощью Орды, |3-6($R)! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?|n|nПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, $N – и получишь награду!', },
    {'Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.', },
  },
  [8296] = {
    'Почетный знак',
    nil,
    nil,
  },
  [8297] = {
    'Ресурсы Низины Арати',
    {'Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!|n|nВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.|n|nИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', },
    {'Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.', },
  },
  [8298] = {
    'Новые ящики с ресурсами',
    {'Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!|n|nВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.|n|nИ вот чего я хочу от вас, $N. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.', },
    {'Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.', },
  },
  [8299] = {
    'Перекрыть линии поставок Аратора',
    {'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.|n|nВы, $N, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.', },
    {'Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', },
  },
  [8300] = {
    'Новые ящики с ресурсами',
    {'Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.|n|nВы, $N, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.', },
    {'Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот.', },
  },
  [8301] = {
    'Путь праведника',
    {'Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и $Gсмог:смогла; доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю.|n|nУлей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость.', },
    {'Принесите Баристолфу 200 фрагментов силитидских панцирей.', },
  },
  [8302] = {
    'Рука праведника',
    {'Старательно выбирай своих представителей, $Gсмертный:смертная;. Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя.|n|nА теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей. Что стоишь? Иди!', },
    {'Принесите Баристолфу 200 фрагментов силитидских панцирей.', },
  },
  [8303] = {
    nil,
    {'Время пришло, $N.|n|nЯ должен извиниться за то, что так долго держал все в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя.', },
    {'Отыщите Анахроноса в Пещерах Времени в Танарисе.', },
  },
  [8304] = {
    'Дражайшая Наталия',
    {'Моя милая Наталия пропала.|n|nЧестно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталия уверяла, что все в порядке и ей необходимо продолжать исследования.|n|nВ последний раз я видел ее, когда она направилась в лагерь Бронзоборода, на юг.|n|nУ меня слишком мало солдат, $N. Сходи в лагерь Бронзоборода и допроси дворфов.', },
    {'Допросите обитателей лагеря Бронзоборода по поручению командира Мар\'алит из Крепости Кенария. Этот лагерь находится южнее Крепости Кенария.|n|nСобрав необходимые сведения, вернитесь к командиру Мар\'алиту.', },
  },
  [8305] = {
    'Давно забытые воспоминания',
    {'В пустыне неподалеку от Силитуса, рядом со священной стеной, есть хрустальная слеза. Эта слеза – символ великих потерь, понесенных во время войны Зыбучих песков. Отыщи эту слезу и загляни в ее глубины, дабы достичь просветления.', },
    {'Отыщите в Силитусе хрустальную слезу и загляните в ее глубины.', },
  },
  [8306] = {
    'В бездне безумия',
    {'Прошу тебя, $N, отправляйся в Улей Регал и узнай, что сталось с моей возлюбленной Наталией. Это будет очень непросто. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья.|n|nИ последнее, $N. Если она в самом деле безумна, как говорят... сделай, что должно.|n|n*Командир Мар\'алит отворачивается в сторону.*', },
    {'Найдите возлюбленную командира Мар\'алита из Крепости Кенария в Силитусе. По имеющим сведениям, госпожу Наталию Мар\'алит можно найти в Улье Регал.|n|nПрежде чем отправляться в улей, не забудьте поговорить с дворфами из лагеря Бронзоборода. Они могут дать пару советов и подкинуть дополнительную работу.|n|nСледует помнить слова командира: "Сделай, что должно..."', },
  },
  [8307] = {
    'Блюдо из червей',
    {'Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю все, что моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало…|n|nЗато я видела, как в лагерях Сумеречного Молота охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь – сообщи мне.', },
    {'Поищите в лагере Сумеречного Молота на западе от Крепости Кенария сведения о приготовлении мяса песчаных червей.', },
  },
  [8308] = {
    'Потерянное письмо Бранна Бронзоборода',
    {'Всем заинтересованным лицам:|n|nЕсли вы читаете это письмо, значит, я мертв или скоро умру. Трудно сказать. Большая часть команды уже мертва.|n|nНашел сведения про титана. Страшная битва между ним и Древним богом. Самый настоящий Древний Бог. Нашел древний туннель в Ан\'Кираж. Иду по нему.|n|nОтнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок.|n|n- Бранн Бронзобород, оперативный исследователь|n|nP.S. Остерегайся безумного ночного эльфа, поклоняющегося Древнему богу.', },
    {'Отнесите письмо Бранна Бронзоборода в лагерь Бронзоборода в южной части Силитуса.', },
  },
  [8309] = {
    'Поиски рун',
    {'После нашего первого рейда в ульи и последовавшего безумия госпожи Мар\'алит, их этих трех ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность связана с письменами, покрывающими эти странные кристаллы.|n|nНам нужны оттиски с кристаллов из всех трех ульев. Заполучив их, мы можем попытаться понять причины этого безумия.|n|nВозьми копирующее устройство геолога и ступай в ульи, $N. Без оттисков из всех ульев даже не возвращайся.', },
    {'Рутгар Знакописец из лагеря Бронзоборода в Силитусе просит отправиться в улья Аши, Зора и Регал и сделать оттиски со всех покрытых письменами кристаллов.|n|nЧтобы сделать приличные копии древних рун, можно воспользоваться копирующим устройством геолога. По выполнении задания вернуться к Рутгару Знакописцу.', },
  },
  [8310] = {
    'Расшифровка',
    {'Мне кажется, я изобрел эликсир, который поможет нам расшифровать письмена и язык силитидов и киражей! Что мне нужно? Хорошо, что ты $Gспросил:спросила;! Мне нужны мозги! Точнее говоря, мозги всех видов силитидов, живущих в ульях. Принеси мне мозги, и работа Рутгара не пойдет насмарку.', },
    {'Добудьте для Франкала Каменного Моста из лагеря Бронзоборода в Силитусе мозг силитидов из ульев Зора, Аши и Регал. По выполнении задания вернитесь к Франкалу.', },
  },
  [8311] = {
    'Тыквовинские вкусности для Джеспера!',
    {'Хотел бы я пойти потыквовинничать, но не могу – приболел. Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберешь, на те, что у меня уже есть. Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки!|n|nУ каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин. Поговори с ними и выполни их задания. А еще в Стальгорне живет гном по имени Талваш, и он тоже раздает сладости. Когда соберешь их все, принеси мне сюда!', },
    {'Поговорите с хозяевами таверн в Штормграде, Стальгорне и Дарнасе, а также с Талвашом дель Кисселем в Стальгорне. Выполните то, что они потребуют за предлагамые ими сладости.|n|nВернитесь к Джесперу в сиротский приют Штормграда и принесите ему марципан Дарнаса, леденец Гномрегана, нугу из Штормграда и конфету Стальгорна.', },
  },
  [8312] = {
    'Тыквовинские вкусности для Крохи!',
    {'Я бы так хотела отправиться за конфетами! Но не могу, потому что болею... Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!|n|nУ всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик в деревне Сен\'джин тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?', },
    {'Поговорите с хозяевами таверн в Оргриммаре, Подгороде и Громовом Утесе и с Кали Ремик из деревни Сен\'джин. Выполните то, что они потребуют, за предлагамые ими сладости.|n|nВернитесь к Крохе в сиротский приют Оргриммара и принесите ей марципан Громового Утеса, леденец троллей Черного Копья, нугу из Оргриммара и конфету Подгорода.', },
  },
  [8313] = {
    'Наделение знаниями',
    {'Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нем упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам.', },
    {'Принесите вырванную страницу с рецептом Каландрате в таверну Крепости Кенария.', },
  },
  [8314] = {
    'Разгадка тайны',
    {'Мы на грани крупного прорыва, $N! Принесенные тобой оттиски позволили нам воссоздать письмена на хрустальной призме. Очевидно, что для киражей и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения.|n|nК несчастью, это все, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах.|n|nОтнеси покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария. Может, она сумеет тебе помочь.', },
    {'Рутгар Знакописец из лагеря Бронзоборода в Силитусе просит вас отнести покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария.', },
  },
  [8315] = {
    'Зов',
    {'Здесь изображена встреча посланника киражей с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника.|n|nЯ создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него...', },
    {'Геолог Ехидная из Крепости Кенария просит добыть открыватель Кристаллов у киражского посланника.|n|nВам следует отнести письмена зова к Костям Граккаронда, на юг от Крепости Кенария, и нарисовать их на песке. Если появится киражский посланник, убейте его и заберите открыватель Кристаллов. При успехе вернитесь к геологу Ехидной.|n|nДля выполнения задания понадобится целая армия!', },
  },
  [8316] = {
    'Оружие войны',
    nil,
    nil,
  },
  [8317] = {
    'Помощь по кухне',
    {'Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копченые пустынные клецки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей.', },
    {'Каландрате из Крепости Кенария необходимы 10 копченых пустынных клецок.', },
  },
  [8318] = {
    'Тайные послания',
    {'Некоторые из служителей культа Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек.|n|nЯ не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!', },
    {'Принесите 10 зашифрованных Сумрачных текстов Бору Буйногривому в Крепость Кенария.', },
  },
  [8319] = {
    'Зашифрованные Сумеречные тексты',
    nil,
    nil,
  },
  [8320] = {
    'Геолорды из культа Сумеречного Молота',
    {'Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы ее стронников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне.|n|nХотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы. Ступай в их лагеря и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!', },
    {'Убейте 10 геолордов из культа Сумеречного Молота и вернитесь к Хууму Буйногривому в Крепость Кенария.', },
  },
  [8321] = {
    'Вайрал Подлый',
    {'Мы обнаружили еще одну базу Сумеречного Молота. Она зовется Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живет именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку.|n|nГоворят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь.', },
    {'Принесите перстень-печатку Вайрала Хууму Буйногривому в Крепость Кенария.', },
  },
  [8322] = {
    'Тухлые яйца',
    {'Люди Южнобережья любят эль, особенно тот, что подают в местной таверне. Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!|n|nВозьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья. Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!|n|nКак только угостите все Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!', },
    {'Бросьте тухлые яйца в главную бочку с пивом в таверне Южнобережья.', },
  },
  [8323] = {
    'Истинно верующие',
    {'Теперь, когда у меня есть Сумеречный словарь, мне остается попросить тебя о небольшой услуге.|n|nВ моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей.|n|nЕсли они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в "Истинно верующем".|n|nХотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота.', },
    {'Принесите 10 зашифрованных Сумеречных текстов отшельнику Ортеллу.', },
  },
  [8324] = {
    'Не теряя веры',
    nil,
    nil,
  },
  [8325] = {
    'Очищение острова Солнечного Скитальца',
    {'Чем скорее ты начнешь свое обучение, $N, тем лучше будет для всех нас. Поскольку права на ошибку у нас нет, слушай внимательно.|n|nПламенеющие кристаллы – зеленые парящие в воздухе объекты к западу от Солнечного Шпиля – используются на нашем острове как источники энергии для проведения магических экспериментов. Маназмеи издревле охраняли их, но во время вторжения Плети в Кель\'Талас наша магическая сила ослабла, и маназмеи вышли из повиновения.|n|nУ нас нет иного выбора, кроме как истреблять их ради очищения острова. Убей несколько маназмеев и возвращайся ко мне.', },
    nil,
  },
  [8326] = {
    'Вынужденные меры',
    {'Благодаря тебе мне удалось кое-что выяснить, но, честно говоря, открытие меня не порадовало. Необузданная мощь пламенеющих кристаллов нарушила природное равновесие острова гораздо сильнее, чем я думала. Так что придется прибегнуть к весьма жестким мерам, чтобы восстановить равновесие.|n|nНекоторые из местных животных, например рыси, попали под влияние кристаллов, и их придется истребить. Принеси мне их ошейники, $N, и я попробую восстановить нашу власть над рысями.', },
    {'Соберите 8 ошейников с убитых рысей-прыголапов и детенышей прыголапов и возвращайтесь к магистру Эроне, ждущей вас на острове Солнечного Скитальца.', },
  },
  [8327] = {
    'Визит к Лантану Перилону',
    {'Ступай к моему помощнику, Лантану Перилону. Он скажет тебе, что делать дальше. Пока мы обуздываем мощь пламенеющих кристаллов, тебе придется заняться Академией Фалтриена. Лантан подробно объяснит тебе все при встрече.|n|nИди на запад по этой тропе и скоро увидишь его.|n|nУдачи, $N, твои труды будут вознаграждены.', },
    {'Поговорите с Лантаном Перилоном на острове Солнечного Скитальца – он стоит рядом с тропой, отходящей на запад от Солнечного Шпиля.', },
  },
  [8328] = {
    'Наставник магов',
    {'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных магов на острове Солнечного Скитальца тренирует Джулия Солнцесвет. Поговори с ней, может быть, она сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.|n|nДжулия, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', },
    {'Поговорите с наставницей магов Джулией Солнцесвет в Солнечном Шпиле на острове Солнечного Скитальца.', },
  },
  [8329] = {
    'Наставник воинов',
    {'По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных воинов на острове Солнечного Скитальца тренирует Джестенис Солнцесвет. Поговори с ним, может быть, он сможет тебя чему-нибудь научить. Это будет стоить денег, так что приходи не с пустыми карманами.|n|nДжестенис, как и все наставники острова Солнечного Скитальца, находится на нижнем этаже Солнечного Шпиля.', },
    {'Поговорите с Джестенисом Солнцесветом – наставником воинов – в Солнечном Шпиле на острове Солнечного Скитальца.', },
  },
  [8330] = {
    'Вещи Соланиана',
    {'Из-за беспорядков в Солнечном Шпиле я не успел собрать свои вещи, которые оставил в разных местах по всему острову. Я не могу бросить свой пост у Солнечного Колодца, поэтому прошу тебя собрать их.|n|nМне нужен мой гадальный шар, дневник и свиток магии Плети. Возьми эту сумку и сложи в нее вещи. Принеси их мне, и я награжу тебя, а в придачу отдам сумку!', },
    {'Верните Соланиану его гадальный шар, дневник и свиток магии Плети. Их можно найти на острове Солнечного Скитальца у пруда, у одного из пламенеющих кристаллов и у фонтана. Вернитесь с вещами к хранителю в Солнечный Шпиль на острове Солнечного Скитальца.', },
  },
  [8331] = {
    'Аурель Золотой Лист',
    {'Мы надеялись, что Сумеречный Молот свернет свои операции в Силитусе... Увы, мы ошиблись. Благодаря постоянным нападением на лагеря сектантов нам удалось выяснить, что Молот контролирует еще более страшная сила, Совет Бездны. Для связи со служителями культа этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны.|n|nПоговори с ремесленницей Аурель Золотой Лист, в восточной части Крепости Кенария. Мы задумали одну хитрость, для которой необходимо ее искусство.', },
    {'Поговорите с Аурель Золотой Лист в Крепости Кенария.', },
  },
  [8332] = {
    'Герцоги Совета',
    {'Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придется связаться с Советом через этот камень и убедить всех, что ты – $Gодин:одна; из командующих среднего ранга Сумеречного Молота.|n|nЧтобы эта хитрость удалась, необходим статусный медальон. Я могу создать его, но мне понадобится большой сверкающий осколок и талисманы храмовников Бездны.|n|nПринеси их мне, а остальное я сделаю сама.', },
    {'Принесите Аурель Золотой Лист в Крепость Кенария 1 большой сверкающий осколок и 3 талисмана Бездны.', },
  },
  [8333] = {
    'Статусный медальон',
    nil,
    nil,
  },
  [8334] = {
    'Агрессия',
    {'Прежде чем направить тебя в академию, я хочу, чтобы ты $Gвыполнил:выполнила; одну задачу, требующую немедленного решения. Некогда древуны помогали нам возделывать наш прекрасный остров, но теперь они вышли из повиновения. Изничтожь их с должной поспешностью, но помни: они очень озлоблены. Именно из-за этого нам приходится истреблять некогда покорных нам слуг.|n|nМне неприятно просить тебя об этом, но выживать – так выживать. Горевать будем потом.', },
    {'Убейте 7 древунов и 7 одичавших древунов, затем вернитесь к Лантану Перилону на острове Солнечного Скитальца.', },
  },
  [8335] = {
    'Фелендрен Изгой',
    {'В академии Фалтриена, что к юго-западу отсюда, живет предатель нашего народа.|n|nЕго зовут Фелендрен. Он был изгнан из земель эльфов крови за то, что не слушал предостережений наших наставников и старейшин. Он изгой нашего общества, ибо живет он лишь для того, чтобы насыщать свою неутолимую жажду магии. Фелендрен не пожелал бороться со своим пагубным пристрастием и превратился в жалкое подобие мыслящего существа. Теперь он один из Презренных, которые угрожают нашему спокойствию! |n|nСрази его и и тех духов, которых он сделал своими приспешниками!', },
    {'Убейте 8 волшебных призраков, 2 нечистых волшебных призрака и Фелендрена Изгоя в академии Фалтриена. Принесите голову Фелендрена Лантану Перилону на остров Солнечного Скитальца.', },
  },
  [8336] = {
    'Пригоршня осколков',
    {'Очень жаль, что мы утратили контроль над многими существами этого острова. Некогда это был оплот спокойствия, трудов и исследований. Теперь мы только и делаем, что отбиваемся от нападений собственных созданий!|n|nВыполни для меня небольшое поручение и получишь волшебный дар. Принеси мне горсть магических осколков. Ты можешь найти их у существ, обладающих магическими способностями. В награду за это я наложу на тебя заклятие, которое поможет тебе в твоих приключениях.', },
    {'Соберите 6 магических осколков, убивая любых существ, обладающих магическими способностями, а затем вернитесь к чародею Итанасу.', },
  },
  [8338] = {
    'Оскверненный магический осколок',
    {'Вы нашли странный магический осколок, обыскав останки нечистого волшебного призрака. Осколок не похож на те, что вам уже попадались. Он темный и выглядит зловеще – прямо как тот дух, у которого вы его забрали. Один вид его на вашей ладони наполняет вас зловещими предчувствиями.|n|nЧародей Хелион возле беседки Солнечного Шпиля на острове Солнечного Скитальца наверняка сможет найти ему применение.', },
    {'Принесите оскверненный магический осколок чародею Хелиону, который стоит возле беседки Солнечного Шпиля на острове Солнечного Скитальца.', },
  },
  [8339] = {
    'Обмануть Совет<NYI> <TXT> UNUSED',
    {'Чтобы сделать перстень-печатку служителей культа Сумеречного Молота, мне понадобится куча предметов', },
    {'Принесите предметы Аурель Золотой Лист в Крепость Кенария.', },
  },
  [8340] = {
    'Сумеречный перстень-печатка',
    nil,
    nil,
  },
  [8341] = {
    'Лорды Совета',
    {'Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но... Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!|n|nДля этого понадобится кольцо Власти, которое носят лишь вожди сектантов. Я готова создать такое кольцо, если ты принесешь мне большие сверкающие осколки и перстни Бездны.', },
    {'Принесите Аурель Золотой Лист в Крепость Кенария 5 больших сверкающих осколков и 3 перстня Бездны.', },
  },
  [8342] = {
    'Кольцо Власти служителя культа Сумеречного Молота',
    nil,
    nil,
  },
  [8343] = {
    'Открытие Золотого Листа',
    {'$N, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты $Gзаслужил:заслужила; уважение всего Круга Кенария. Мы знаем, что ты – $Gединственный:единственная;, кому по плечу такое задание.|n|nЖелаю удачи, $N. Когда решишь приняться за это задание, поговори с Аурель.', },
    {'Поговорите с Аурель Золотой Лист в Крепости Кенария.', },
  },
  [8344] = {
    'Постижение основ',
    {'Внимай моим словам, $Gюноша:дева;, этот остров поражен порчей, и она куда сильнее, чем последствия удара Плети.|n|nЯ уверен, что на острове затаились демоны.|n|nК западу ты увидишь шпили академии Фалтриена. Волшебные призраки, что наводнили ее, – источники демонической силы. Принеси мне сущности этих духов.|n|nЗа твое послушание я научу тебя призывать беса – твоего первого спутника на долгом пути чернокнижника.', },
    {'Принесите 4 призрачные сущности и 1 оскверненную призрачную сущность призывателю Тель\'Лариену в Солнечный Шпиль на остров Солнечного Скитальца.', },
  },
  [8345] = {
    'Святилище Дат\'Ремара',
    {'День за днем я стою здесь и смотрю на море. Глаза мои устремлены к горизонту, и люди говорят, что я живу лишь прошлым. Но я твердо убежден, что каждый, кто попадает на этот остров, обязан почтить память героев, пожертвовавших собой ради нашего народа.|n|nДат\'Ремар Солнечный Скиталец был нашим первым королем. Он привел нас сюда из Калимдора через бурный Водоворот.|n|nНайди его святилище на западе отсюда и не возвращайся, пока не прочтешь надпись, посвященную памяти короля.', },
    {'Прочтите надпись на святилище Дат\'Ремара и вернитесь к Хранителю Колодца Соланиану в Солнечный Шпиль на острове Солнечного Скитальца.', },
  },
  [8346] = {
    'Неутолимая жажда',
    nil,
    nil,
  },
  [8347] = {
    'Помощь Курьерам',
    {'Магистр Эрона желает, чтобы ты $Gнаправился:направилась; в город Луносвет и $Gпомог:помогла; нам восстановить его... Она начала питать к тебе особое доверие после того, как ты $Gразрешил:разрешила; ситуацию в академии Фалтриена. Не разочаруй нас, $N.|n|nПо дороге на Площадь Соколиных Крыльев, к югу отсюда, поговори с гонцом Аларион. Ты найдешь ее неподалеку от моста.|n|nКурьеры заботятся о перевозке грузов отсюда на континент и обратно, и ты $Gмог:могла; бы оказать им существенную помощь в этом деле.', },
    {'Поговорите с гонцом Аларион у моста к югу от острова Солнечного Скитальца.', },
  },
  [8348] = {
    'Перстень герцогов',
    {'Хуум говорит, что ты $Gпридумал:придумала;, как вызвать герцогов Бездны! Это большое достижение.|n|nЗнаешь, что бы еще хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чем я. В доказательство собственного подвига принеси перстень герцога.', },
    {'Принесите перстень Бездны Бору Буйногривому из Крепости Кенария.', },
  },
  [8349] = {
    'Бор Буйногривый',
    {'Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.|n|nУдачи, $N. Если тебе снова понадобятся медальоны, возвращайся ко мне.', },
    {'Поговорите с Бором Буйногривым из Крепости Кенария.', },
  },
  [8350] = {
    'Доставка свертка',
    {'Гибель еще одного нашего курьера – истинная трагедия, но это неизбежные издержки нашего ремесла. Нужно как можно быстрее доставить этот сверток магистру Эроне на постоялый двор на Площади Соколиных Крыльев.|n|nНам недостает курьеров, и мне больше некому дать это поручение.|n|nНе скрою – путь на Площадь Соколиных Крыльев станет чрезвычайно опасен, как только ты покинешь пределы Рассветной улицы. Возьмешься за это дело, $N?', },
    {'Доставьте сверток Эроны хозяйке таверны Деланиель на Площадь Соколиных Крыльев в Лесах Вечной Песни.', },
  },
  [8351] = {
    'Разговор с Бором',
    {'Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию...', },
    {'Поговорите с Бором Буйногривым из Крепости Кенария.', },
  },
  [8352] = {
    'Скипетр Совета',
    {'Мы с Хуумом только что обсуждали тебя. Он говорит, что ты $Gготов:готова; испытать себя и сразиться с лордом Бездны!|n|nДолжен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!|n|nЕсли ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждет великая награда.', },
    {'Принесите скипетр Бездны Бору Буйногривому из Крепости Кенария.', },
  },
  [8353] = {
    'Курочка с мятой',
    {'А, тыквовинничаем для больных деток? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...|n|nЧто же, за мое лакомство – мятную конфету Стальгорна – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, может и не любят... главное, что конфетку ты не получишь, пока не поквохчешь!|n|nНу что, |3-6($C), будешь квохтать или нет?! Пора отрабатывать лакомство!', },
    {'Изобразите курицу для хозяина таверны Огневара.', },
  },
  [8354] = {
    'Курочка с мятой',
    {'А, ты у нас сегодня вместо детишек, да? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...|n|nЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!|n|nНу что, |3-6($C), будешь квохтать или нет?! Пора отрабатывать лакомство!', },
    {'Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!', },
  },
  [8355] = {
    'Плата за леденцы',
    {'А, тебе нужны сладости! Ха-ха!|n|nНу, хотя ты и доброе дело делаешь, собирая сладости для детишек, так просто я тебя не отпущу. Есть у меня вкусные леденцы Гномрегана, и я отдам их детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За паровоз – целый леденец!|n|nТу-ту, |3-6($C)!', },
    {'Изобразите паровозик для Талваша дель Кисселя.', },
  },
  [8356] = {
    'Поиграй мускулами!',
    {'Какой у тебя... интересный костюмчик. Несмотря на то, что ты по доброте своей помогаешь ребенку получить сладости, мне все же придется попросить тебя сделать что-нибудь!|n|nНу-ка, ну-ка... ты выглядишь $Gтаким сильным и мускулистым:такой сильной и мускулистой; в этом... наряде... посмотрим-ка на твои бицепсы! Да, давай, поиграй-ка мускулами, $Gсилач:силачка;!|n|nПоиграешь мускулами – дам тебе вкуснейшей нуги. Это отличное тыквовинское угощение!', },
    {'Поиграйте мускулами перед хозяйкой таверны Аллисон и получите от нее за это нугу из Штормграда.', },
  },
  [8357] = {
    'Танец за марципан',
    {'Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...|n|nДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!', },
    {'Потанцуйте для хозяйки таверны Салиенны, и за это вы получите марципан Дарнаса!', },
  },
  [8358] = {
    'Плата за леденцы',
    nil,
    {'Изобразите паровозик перед Кали Ремик и получите в награду леденец троллей Черного Копья!', },
  },
  [8359] = {
    'Поиграй мускулами!',
    {'Ой, какой интересненький костюмчик! Нет, ты, конечно, $Gхороший мальчик:хорошая девочка;, раз помогаешь ребенку собрать сладости, но, боюсь, тебе все же придется выполнить для меня какое-нибудь задание, прежде чем ты получишь конфету.|n|nДай-ка подумать... У тебя такой накачанный вид в этом... костюмчике! Поиграй-ка мускулами!|n|nА я тебе за это дам вкусной оргриммарской нуги. Дети ее очень любят!', },
    {'Поиграйте мускулами перед хозяйкой таверны Гришкой и получите от нее за это нугу из Оргриммара.', },
  },
  [8360] = {
    'Танец за марципан',
    {'Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...|n|nДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!', },
    {'Потанцуйте для хозяйки таверны Палы, и за это вы получите марципан Громового Утеса!', },
  },
  [8361] = {
    'Связь с Бездной',
    {'Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им служители культа или используют как посредников при общении с еще более страшными силами. Ясно одно – они получают приказы от этих элементалей.|n|nОтыщи храмовника Бездны и задай ему хорошую трепку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига.', },
    {'Убейте храмовника Бездны по поручению Бора Буйногривого из Крепости Кенария, что в Силитусе, и принесите в доказательство талисман Бездны.', },
  },
  [8362] = {
    'Талисманы Бездны',
    nil,
    nil,
  },
  [8363] = {
    'Перстни Бездны',
    nil,
    nil,
  },
  [8364] = {
    'Скипетры Бездны',
    nil,
    nil,
  },
  [8365] = {
    'Пиратские шляпы',
    {'Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, |3-6($C). Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.|n|nВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?', },
    {'Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Картеля в Танарисе.', },
  },
  [8366] = {
    'Покажи этим пиратам',
    {'Они требуют от меня невозможного!|n|nКартель Хитрая Шестеренка хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.|n|nВ последнее время пираты забыли, что Картель платит им за защиту. Нужно показать им, что к чему.|n|nПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, $N. Я твой должник!', },
    {'Начальник отдела безопасности Чепухастер из Порта Картеля в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 сорвиголов Южных морей.', },
  },
  [8367] = {
    'Великая честь',
    {'Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.|n|nСтупай же и сокруши противника на всех фронтах. За честь! За Орду!', },
    {'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.', },
  },
  [8368] = {
    'Битва за Ущелье Песни Войны',
    {'Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.|n|nНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!', },
    {'Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.', },
  },
  [8369] = {
    'Вторжение в Альтеракскую долину',
    {'Слушай, $N. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!', },
    {'Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поле боя.', },
  },
  [8370] = {
    'Завоевание Низины Арати',
    {'Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.|n|nВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $N!', },
    {'Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.', },
  },
  [8371] = {
    'В едином порыве',
    {'В войне против Орды решающей может оказаться любая битва, $Gсынок:дочка;.|n|nПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.|n|nАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.', },
    {'Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.', },
  },
  [8372] = {
    'Битва за Ущелье Песни Войны',
    {'Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.|n|nЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.|n|nВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $N! За Альянс!', },
    {'Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.', },
  },
  [8373] = {
    'Сила сосен',
    {'Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?|n|nКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.|n|nПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?', },
    {'Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Дыгалу.', },
  },
  [8374] = {
    'Завоевание Низины Арати',
    {'Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.|n|nРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.|n|nЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!', },
    {'Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.', },
  },
  [8375] = {
    'Помни Альтеракскую долину!',
    {'Не пойми меня превратно, $N. Орда совершенно справедливо считает долину Альтерака территорией клана Северного Волка.|n|nВидишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка.|n|nВечная память отважным дворфам, павшим от рук вероломных орков. Ступай, |3-6($C), внеси свой вклад в битву за Альтеракскую долину. За Альянс!', },
    {'Принесите 3 почетных знака Альтеракской долины бригадному генералу Альянса рядом со входом на поле боя.', },
  },
