  [8728] = {
    'Хорошая новость и плохая новость',
    {'Что же, это оказалось дольше, чем я думал. Давай-ка посмотрим, что написано в этой книге.|n|n*Нарайн молча читает книгу, периодически что-то бормоча себе под нос.*|n|nХорошая новость – я на 99%уверен, что смогу сделать арканитовый буек, который будет работать согласно вашим требованиям. А вот это полностью зависит от плохих новостей.|n|nА плохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов.|n|nПринесите мне все, что надо, и я сделаю буек.', },
    {'Нарайн Причудень и Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.', },
  },
  [8729] = {
    'Гнев Нептулона',
    {'Я еще не говорил о плохой новости, нет??? Ее зовут Каракула – 30 метров смерти и разрушения. Наверное, я забыл об этой мелочи.|n|nМое сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буек с берега Азшары, в Штормовую бухту.|n|nВысматривайте водоворот, в котором скорее всего будет до кучи обломков кораблей.|n|nКстати, надеюсь, не в одиночку пойдете?|n|nЕсли вам каким-то чудесным образом повезет, отнесите обломок скипетра Анахроносу.', },
    {'Забросье арканитовый буй в Водоворот в Штормовой бухте Азшары.', },
  },
  [8730] = {
    'Нефариус, пораженный порчей',
    {'Надо же, герой! Тысячу лет назад мне поручили хранить осколок, и вот, в черный час он был отнят у меня... Но какая же трагедия без жестокости?|n|n*Веластрас слабо кашляет.*|n|nОс... осколок скипетра ныне у Нефариуса.|n|nВремя дорого, ибо Нефариус намерен уничтожить осколок. Поторопись!', },
    {'Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.', },
  },
  [8731] = {
    'Рутинное задание',
    {'Приветствую тебя, $N. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.|n|nЛегион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал.|n|nПоговори с капитаном и принеси мне доказательство выполнения его указаний. Тем временем я подготовлю для тебя новое задание.|n|nАх да, сделай одолжение, держись подальше от дружины Стальгорна. Добровольцы Орды и Альянса постоянно грызутся друг с другом.', },
    {'Поступите в распоряжение легиона Оргриммара возле Улья Регал. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях, отнесите их Зовущему Калдону в Крепость Кенария.|n|nВнимание: исцеление или наложение благоприятных заклинаний на бойцов легиона Оргриммара переводит в режим PvP.', },
  },
  [8732] = {
    'Бумаги о полевых обязанностях',
    nil,
    nil,
  },
  [8733] = {
    'Эраникус, Тиран Сна',
    {'Это будет расплата. Если я сегодня погибну, то паду я за правое дело. Верни осколок зеленого жезла. Освободи Эраникуса от порчи, которой поразили его Древние Боги.|n|nОтправляйся в Дарнас. Прямо у стен города ты встретишь одного из моих агентов. Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем.|n|n*Малфурион вздыхает.*|n|nУтратить милость тысячелетий...', },
    {'Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнаса.', },
  },
  [8734] = {
    'Тиранда и Ремул',
    {'Тиранда будет извещена, $Gсмертный:смертная;. Шан\'до Ярость Бури подготовил меня к неожиданностям.|n|nТеперь тебе надлежит отправится в Лунную поляну и поговорить с хранителем Ремулом. Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса.|n|nМы все желаем тебе великой удачи.', },
    {'Отправляйтесь в Лунную поляну и поговорите с хранителем Ремулом.', },
  },
  [8735] = {
    'Проклятие Кошмара',
    {'Тебе нужно оправиться к четырем порталам сна Азерота. Из каждого ты добудешь фрагмент проклятия Кошмара. Дракониды, населяющие те места, не будут их отдавать. Возвращайся, когда добудешь все фрагменты.', },
    {'Отправьтесь к четырем порталам Изумрудного Сна в Азероте и добудьте фрагменты проклятия Кошмара из каждого из них. Вернитесь к хранителю Ремулу в Лунную поляну по завершении задания.', },
  },
  [8736] = {
    'Явление Кошмара',
    {'Мы должны усмирить Эраникуса. Мы не можем позволить ему уничтожить себя!|n|nТиранда уже идет нам на помощь. Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения.|n|nСтой на страже! Ты и твои союзники – наша единственная надежда.', },
    {'Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.', },
  },
  [8737] = {
    'Лазурный храмовник',
    {'Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.|n|nОтыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому.', },
    {'Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из Крепости Кенария. Для завершения задания принесите тактическую задачу I.', },
  },
  [8738] = {
    'Донесение разведчика из Улья Регал',
    {'Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых. Найди его и забери у него письменный отчет. Нам необходимо как можно скорее получить собранные сведения.', },
    {'Свяжитесь с кенарийским разведчиком Ландионом в Улье Регал и отнесите донесение разведчика из Улья Регал Зовущей из клана Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VII.', },
  },
  [8739] = {
    'Донесение разведчика из Улья Аши',
    {'Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить собранные сведения.', },
    {'Свяжитесь с кенарийской разведчицей Джалией в Улье Аши и отнесите ее донесение призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VIII.', },
  },
  [8740] = {
    'Сумеречные мародеры',
    {'В последнее время появились верховые отряды сторонников Сумеречного Молота. Они не суются в земли, охраняемые Крепостью Кенария, а грабят небольшие караваны и отряды.|n|nНайди и убей сумеречных мародеров, а заодно и их лидера, воительницу по имени Морна. О выполнении задания доложи Зовущей из клана Гордый Рог.', },
    {'Убейте сумеречного мародера Морну и двух сумеречных мародеров. Доложите о выполнении задания Зовущей из клана Гордый Рог. Кроме того, сдайте тактическую задачу IX.', },
  },
  [8741] = {
    'Возвращение победителя',
    {'Хранитель ждет твоего возвращения, $N. Отнеси этот осколок зеленого скипетра Анахроносу в Пещеры Времени.', },
    {'Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.', },
  },
  [8742] = {
    'Армия Калимдора',
    nil,
