  [8883] = {
    'Валадар Звездная Песня',
    {'Раз у тебя есть приглашение на Лунный фестиваль, можешь отправляться в Лунную поляну! Там полно веселых гуляк, а в деревне Ночная Гавань Валадар Звездная Песня и его сестра Фариэль приглашают всех принять участие в празднике.|n|nОтправляйтесь в Лунную поляну через большой круг лунного света и поговорите с Валадаром – узнайте, какие призы могут перепасть вам во время праздника!', },
    {'Используйте приглашение на Лунный фестиваль, стоя в столпе лунного света, чтобы переместиться в Лунную поляну. Прибыв на место, поговорите с Валадаром Звездной Песней в деревне Ночная Гавань.', },
  },
  [8884] = {
    'Рыбьи головы, рыбьи головы...',
    {'Приветствую тебя, |3-6($C). Посмотри-ка вон туда, в сторону моря. Что ты видишь? Правильно, наш пляж... Наш Безмятежный берег. Но теперь на нем кишат гнусные твари, именуемые мурлоками!|n|nЭто оскорбление для всех нас!|n|nУ меня есть для тебя задание – если ты сочтешь, что оно тебе по плечу. Мне нужны их головы! Посмотрим; возможно, если нам удастся значительно сократить их численность, эти твари испугаются и вернутся обратно в свои темные глубины, откуда выползли!', },
    {'Добудьте 8 голов мурлоков из племени Темной Чешуи. Принесите их Гатвелиону Солнечному Взору в Лесах Вечной Песни на утес над Безмятежным берегом.', },
  },
  [8885] = {
    'Кольцо Мррргла',
    {'Мурлоки из племени Темной Чешуи не испугались тебя! Но я, кажется, знаю, как им отомстить – и заодно заставить их собирать вещички!|n|nУ этих мурлоков есть главарь, который зовет себя Мррргл. Он бродит по Золотистому взморью, к югу от устья реки. Эта тварь некогда убила моего земляка и теперь нагло носит его кольцо!|n|nУбей Мррргла и принеси мне кольцо моего товарища. Уж тогда-то мы сумеем запугать этих чудищ!', },
    {'Снимите кольцо Мррргла с трупа предводителя племени Темной Чешуи. Верните его Гатвелиону Солнечному Взору в Лесах Вечной Песни на утесе над Безмятежным берегом.', },
  },
  [8886] = {
    'На помощь! Пираты!',
    {'Ох, |3-6($C), как хорошо, что ты здесь! Эти склизкие мурлоки захватили мой груз! Мало того, что все магические товары, которые я везла, разграблены Презренными, так теперь все остальное попало в лапы к мурлокам! Куда катится эта страна?!|n|nНе можешь ли ты выручить мой груз? Нет, я не рассчитываю, что ты спасешь все, но сейчас я буду благодарна хотя бы за часть груза! Я уверена, во всем виноваты мурлоки племени Темной Чешуи, которые живут в хижинах к западу и к югу от стоянки Золотистого взморья!', },
    {'Отыщите 6 тюков из груза капитана Келисендры и верните их капитану Келисендре в укрепленный лагерь к востоку от Причала Солнечного Паруса в Лесах Вечной Песни.', },
  },
  [8887] = {
    'Утраченные бумаги капитана Келисендры',
    {'Интересно... У вас в руках водонепроницаемый кожаный футляр, внутри которого множество листов пергамента. Судя по обозначениям, это навигационные карты, подписанные капитаном Келисендрой.|n|nВы уже слышали о небольшом укрепленном лагере к востоку от Причала Солнечного Паруса. Может быть, там вы найдете капитана?', },
    {'Верните утраченные бумаги капитану Келисендре в укрепленный лагерь к востоку от Причала Солнечного Паруса в Лесах Вечной Песни.', },
  },
  [8888] = {
    'Ученица магистра',
    {'$C, выслушай мою просьбу! Я решил закрыть одну из своих школ – по причинам, в которые я сейчас вдаваться не могу. И несколько дней назад я отправил туда с этой целью одну из моих учениц, Лоралталис. И с тех пор о ней ни слуху, ни духу!|n|nПрошу тебя, сходи в Замок Блеклых Сумерек, узнай, как она там, и все ли с ней в порядке. От Обители Странников ступай по тропе на север, потом на развилке поверни направо.', },
    {'Поговорите с ученицей Лоралталис возле Замка Блеклых Сумерек в Лесах Вечной Песни.', },
  },
  [8889] = {
    'Отключить замок',
    {'Как тебе, должно быть, известно, магистр Блеклых Сумерек прислал меня сюда, чтобы отключить источники энергии, питающие замок. Их три, они находятся в разных местах внутри замка.|n|nУвы, я, похоже, опоздала: Замок Блеклых Сумерек захватили странные магические твари. Мне не хватает опыта, чтобы выполнить эту задачу, но, думаю, $Gтакой умелый:такая умелая:c; |3-6($C), как ты, с этим справится...', },
    {'Отключите 3 источника энергии в Замке Блеклых Сумерек. Потом верните обезвреживающий самоцвет ученице Лоралталис в Лесах Вечной Песни.', },
  },
  [8890] = {
    'Весточка из замка',
    {'$N, я хочу попросить тебя о последней услуге. Не согласишься ли ты вернуться в Обитель Странников и рассказать магистру Блеклых Сумерек о том, что здесь произошло? Пусть знает, что со мной все в порядке, но имеет в виду, что некоторые из учеников стали Презренными!|n|nСпасибо тебе за помощь!', },
    {'Вернитесь к магистру Блеклых Сумерек в Обитель Странников в Лесах Вечной Песни.', },
  },
  [8891] = {
    'Неоконченное исследование',
    {'Вы обнаружили тетрадь, похожую на журнал наблюдений, забытый магистром Блеклых Сумерек. Проглядев журнал, вы понимаете, что магистр проводил весьма рискованные эксперименты, пытаясь фильтровать потоки оскверненной магии. Возможно, это объясняет то, что произошло в замке. Магистр наверняка будет рад получить эту тетрадь обратно...', },
    {'Верните журнал магистру Блеклых Сумерек в Обитель Странников в Лесах Вечной Песни.', },
  },
  [8892] = {
    'Проблемы на Причале Солнечного Паруса',
    {'Причал Солнечного Паруса захватили Презренные. Как только мы сумеем подвести туда подкрепление, мы покажем этим уродам, почем фунт лиха!|n|nА пока что ты, $N, можешь нам помочь: поучи их слегка уму-разуму. Сходи туда и покажи им, что с нами шутить опасно. Причал Солнечного Паруса находится к западу от деревни Легкий Ветерок.', },
    {'Убейте 5 презренных-лиходеев и 5 презренных-бесчинников и доложите об этом следопыту Деголайну из Лесов Вечной Песни.', },
  },
  [8893] = {
    'Супер Яйц-О-Матик',
    nil,
    nil,
  },
  [8894] = {
    'Зачистка территории',
    {'Ужас, просто ужас! В замке творится неизвестно что, магистр и все его ученики разбежались, и не успели мы глазом моргнуть, как оказалось, что повсюду кишат эти магические твари! А Виллитену кто-нибудь что-нибудь сказал? Ни словечка!|n|nПослушай, |3-6($C), твой долг – помочь мне разогнать этих мерзких существ! Я не могу поддерживать порядок, пока вокруг бесчинствуют эти "аномальные явления"!', },
    {'Убейте 6 мана-змеев и 6 исчадий эфира и вернитесь к Виллитену Хранителю Земель в Земли Блеклых Сумерек в Лесах Вечной Песни.', },
  },
  [8895] = {
    'Послание в Северное святилище',
    {'Приятно видеть, что ты хоть на что-то $Gспособен:способна;, $N. Ну, раз уж ты так стремишься себя показать, вот тебе новое задание.|n|nВот письмо хранителю энергии Кайданису, чародею, отвечающему за Северное святилище. Отправляйся на юго-запад от Площади Соколиных Крыльев, и найдешь его. Это очень важная персона, так что смотри, не досаждай ему пустой болтовней!', },
    {'Доставьте непомеченное письмо хранителю энергии Кайданису в Северном святилище в Лесах Вечной Песни.', },
  },
  [8896] = {
    'Дворфский шпион',
    {'Так ты говоришь, что эти бумаги были у ночного эльфа? Язык-то, по большей части, дворфийский…|n|nГеолог Страж Наковальни! Его прислали сюда из Стальгорна с дипломатической миссией! Мне следовало заподозрить, что он не случайно интересуется нашими волшебными святилищами! $N, отыщи этого дворфа в Северном святилище и разберись с ним. Да, и сделай это тихо!', },
    {'Найдите и убейте геолога Стража Наковальни в Северном святилище, затем доложите о выполнении задания Аэльдону Озаренному Солнцем из Лесов Вечной Песни.', },
  },
  [8897] = {
    'Дорогая моя Колара!',
    {'Я должен нести стражу здесь, у ворот, но я не могу выбросить из головы мысли о моей милой Коларе. В лучшем случае я могу видеться с нею лишь по несколько часов... Да и что я собой представляю? Я получаю жалованье младшего офицера и со дня на день меня могут отправить на фронт.|n|nНе забудет ли она обо мне сразу же после расставания? В городе полно мужчин, и многие из них богаты.|n|nНо, как бы то ни было, я написал тут несколько слов... в общем, ничего особенного, но я буду признателен, если ты доставишь ей эту записку от меня.', },
    {'Отнесите написанную со старанием записку лейтенанта Хельдрика Коларе Дин, живущей недалеко от банка в Штормграде.', },
  },
  [8898] = {
    'Дорогая моя Колара!',
    {'В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку. Она похитила мое сердце. Я не могу не думать о ней! Я хотел бы послать ей это письмо – я переписывал его двенадцать раз.|n|nПочта сейчас так загружена, а я хотел бы точно знать, что письмо попадет к ней.|n|nЕсли ты направляешься туда, то не окажешь ли мне услугу?', },
    {'Отнесите смятое письмо Коларе Дин, обитающей поблизости от банка в Штормграде.', },
  },
  [8899] = {
    'Дорогая моя Колара!',
    {'Как описать ее красоту? Тысячи лет я учился выражать свои мысли словами, но ныне я нем. |n|nЭти смертные вводят в смущение разум и превращают нас в лепечущих чушь идиотов.|n|nЯ слишком долго смотрел на эти слова. Я больше не могу выжать из них ни капли смысла и убедительности. Нет, она должна получить это послание немедленно, или кто-нибудь другой привлечет ее внимание.', },
    {'Отнесите безукоризненное письмо Коларе Дин, обитающей поблизости от банка в Штормграде.', },
  },
  [8900] = {
    'Дорогая моя Эления!',
    {'Она была такой грустной. Я понял это, едва взглянув на выражение ее лица. Я имею в виду, она казалась грустной – понимаешь? |n|nА после того, как я поговорил с ней, возникла взаимосвязь. Я не думал, что кто-то может понять меня, но она смогла.|n|nКогда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал. Но я скучаю по ней. Ты не можешь отнести ей от меня письмо? Я хочу быть уверен, что оно попадет к ней в руки.', },
    {'Отнесите слегка помятую записку Элении Хайдон, обитающей поблизости от банка в Подгороде.', },
  },
  [8901] = {
    'Дорогая моя Эления!',
    {'Известно ли тебе, что такое любовь, $Gюноша:девушка;? До недавнего времени, пока я не повстречал создание по имени Эления из Подгорода, это чувство было мне не знакомо. Таурены вообще редко обращают внимание на представителей других рас, тем более, если это кто-то из Отрекшихся. Но сейчас я днями и ночами думаю только о ней.|n|nТы не $Gмог:могла; бы отнести ей это письмо? Я хочу, чтобы она приехала в Мулгор. Надеюсь, она согласится.', },
    {'Отнесите написанное со старанием письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.', },
  },
  [8902] = {
    'Дорогая моя Эления!',
    {'Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства. Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли. |n|nБыть может даже тогда, когда все ушло, в нашей жизни все-таки остается место для любви.|n|nЯ уверен, что она тоже изменилась. Ты не передашь ей от меня письмо? Я слишком волнуюсь, чтобы передать его лично.', },
    {'Отнесите проникнутое любовью письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.', },
  },
  [8903] = {
    'Опасная любовь',
    {'И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.|n|nДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.|n|nОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.', },
    {'Раздобудьте открытку штормградского стражника и отдайте ее Аристану Моттару в Штормграде.', },
  },
  [8904] = {
    'Опасная любовь',
    {'И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.|n|nДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.|n|nОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.', },
    {'Раздобудьте заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.', },
  },
  [8905] = {
    'Серьезное предложение',
    {'Рада встрече, |3-6($C). У меня найдется кое-что интересное для тебя.|n|nЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.|n|nКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', },
    {'Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне.', },
  },
  [8906] = {
    'Серьезное предложение',
    {'Рада встрече, |3-6($C). У меня найдется кое-что интересное для тебя.|n|nЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.|n|nКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', },
    {'Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручниками загонщика Делиане в Стальгорне.', },
  },
  [8907] = {
    'Серьезное предложение',
    {'Рада встрече, |3-6($C). У меня найдется кое-что интересное для тебя.|n|nЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.|n|nКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', },
    {'Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручниками Магистра Делиане в Стальгорне.', },
  },
  [8908] = {
    'Серьезное предложение',
    {'Рада встрече, |3-6($C). У меня найдется кое-что интересное для тебя.|n|nЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.|n|nКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.', },
    {'Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручами светлой стали Делиане в Стальгорне.', },
  },
