  [8919] = {
    'Серьезное предложение',
    {'Привет тебе, |3-6($C)! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!|n|nОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.|n|nМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', },
    {'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Багрового Тумана Моквару в Оргриммар.', },
  },
  [8920] = {
    'Серьезное предложение',
    {'Привет тебе, |3-6($C)! Судя по тому, как ты держишься, тебе немало довелось повидать на белом свете. Но бьюсь об заклад, что таких доспехов, как эти, тебе видеть не доводилось!|n|nОкажи мне небольшую услугу, и я отдам их тебе в обмен на наручи попроще.|n|nМне нужен яд тварей, обитающих в Силитусе. Принеси мне этот яд и немного золотых монет, и я произведу обмен.', },
    {'Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами Доблести Моквару в Оргриммар.', },
  },
  [8921] = {
    'Эктоплазматический дистиллятор',
    {'А, тебе нужен мой последний проект… спектральный сканер иных измерений! К сожалению, мне не хватает средств и сотрудников.|n|nХочешь помочь? Великолепно! Первым делом нам придется добыть самую сущность смерти! Эктоплазматический дистиллятор будет нелегко построить, $N.|n|nМне понадобится арканитовый преобразователь, несколько великих вечных субстанций и масло каменного угря. Пригодится и вулканический пепел из прудов лавы в Пылающих степях – из него я сделаю фильтр.', },
    {'Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих вечных субстанции, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых.', },
  },
  [8922] = {
    'Сверхъестественное устройство',
    {'Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!|n|nЯ знаю одного инженера, который чрезвычайно интересуется сверхъестественным. Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!|n|nТа кровь, что ты $Gсобрал:собрала;, предназначается как раз ему. Поезжай в Прибамбасск и отдай ее ему в оплату услуг!', },
    {'Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе.', },
  },
  [8923] = {
    'Сверхъестественное устройство',
    {'Ты все еще здесь? Да, храбрости тебе не занимать! Наверное, тебя заинтересовали те наручи, что я тебе дал. Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне.|n|nТот яд, что я собирал, предназначен для моего знакомого, Мукса Маноскреба. Это инженер, который увлекается всем сверхъестественным. Сейчас он пытается построить прибор, с помощью которого можно общаться с мертвыми! Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет.', },
    {'Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск.', },
  },
  [8924] = {
    'В поисках эктоплазмы',
    {'Отличная конструкция, вот что я скажу! Впрочем, тебе придется попутешествовать, чтобы отыскать бестелесную нежить, без которой не обойтись.|n|nВидишь ли, разный климат оказывает разного рода воздействие на спектральную ткань мертвецов. Там понадобится эктоплазма от страдающих ночных эльфов Силитуса, духов высокорожденных из Зимних Ключей и призраков и банши из Восточных Чумных земель. Не забудь установить дистиллятор, прежде чем приступать к делу!', },
    {'Воспользуйтесь эктоплазматическим дистиллятором рядом с бестелесной нежитью и соберите 12 образцов опаленной эктоплазмы в Силитусе, 12 образцов замороженной эктоплазмы в Зимних Ключах и 12 образцов стабильной эктоплазмы в Восточных Чумных землях. Принесите их вместе с эктоплазматическим дистиллятором Муксу Маноскребу в Прибамбасск.', },
  },
  [8925] = {
    'Портативный источник энергии',
    {'Теперь нам понадобится стабильный и портативный источник энергии, который сможет поддерживать эктоплазму в активной форме. До меня дошли слухи о могущественном элементале по имени Повелитель магмы Бокк. Его сердце состоит из магмы, и это бесконечный источник тепла!|n|nГоворят, что его можно отыскать в Пылающих степях, на юге от Черной горы. Принеси мне магмовое ядро и мы обеспечим энергией спектральный сканер иных измерений!', },
    {'Отыщите в Пылающих степях Повелителя магмы Бокка, добудьте его магмовое ядро и отнесите его Муксу Маноскребу в Прибамбасск.', },
  },
  [8926] = {
    'Справедливое вознаграждение',
    {'Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защишала; мою шкуру, то награда должна быть соотвествующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', },
    {'Принесите пояс дикого cердца и пару перчаток дикого cердца в Стальгорн Делиане.', },
  },
  [8927] = {
    'Справедливое вознаграждение',
    {'Ты $Gоказался:оказалась; чрезвычайно надежным $Gпомощником:помощницей;, $N! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!|n|nОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.', },
    {'Принесите Моквару в Оргриммар пояс дикого cердца и перчатки дикого cердца.', },
  },
  [8928] = {
    'Сомнительный торговец',
    {'Сердечник снабдит наше устройство энергией, остается найти жезл, который будет должным образом направлять ее и при этом не расплавится.|n|nЗнавал я одного беса из Зимних Ключей, который продавал самые разные товары. У него был жезл Стихий, который бы идеально подошел. Так и пнул бы себя – что стоило купить?|n|nОн живет в пещере у входа в Теснину Зловещего Шепота. Прокрадись туда и отыщи его.|n|nИ не давай ему больше сорока золотых – такую цену он назвал мне!', },
    {'Отыщите беса в пещере у входа в Теснину Зловещего Шепота в южной части Зимних Ключей, купите жезл Скверны Стихий и отнесите его Муксу Маноскребу в Прибамбасск.', },
  },
  [8929] = {
    'В поисках Антиона',
    {'Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. |n|nПопробуй воспользоваться этим изобретением там, возможно, тебе удасться узнать то, что знал Антион.', },
    {'Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.', },
  },
  [8930] = {
    'В поисках Антиона',
    {'Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. |n|nПопробуй воспользоваться этим изобретением там, возможно, с его помощью и в самом деле можно говорить с мертвыми.', },
    {'Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.', },
  },
  [8931] = {
    'Справедливое вознаграждение',
    {'Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защишала; мою шкуру, то награда должна быть соотвествующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.', },
    {'Принесите пояс загонщика и пару перчаток загонщика в Стальгорн Делиане.', },
  },
  [8932] = {
