  [9076] = {
    'Главарь Презренных',
    {'Презренные настолько упиваются своей нечистой магией, что они даже не осознали, что нам удалось вернуть себе большую часть прежнего оружия. Однако мы не можем рассчитывать, что они будут долго пребывать в растерянности. Сейчас самое время избавиться от их предводителя, Алдарона. Его видели на верхнем этаже здания у причала. Принеси мне его голову, и я вознагражу тебя по заслугам.', },
    {'Принесите голову Алдарона Велендрису Белому Рассвету у Причала Солнечного Паруса в Лесах Вечной Песни.', },
  },
  [9077] = {
