  [9119] = {
    'Авария в Западном святилище',
    {'Раз уж ты здесь, $N, я попрошу тебя об услуге. Сюда прибегал ученик хранительницы энергии Велании и просил помощи. Судя по всему, в Западном святилище произошла авария. А я был несколько занят нашим... весьма любезным... гостем, дворфом. Узнай, не сможешь ли ты ей помочь. Западное святилище – к юго-западу отсюда.', },
    {'Поговорите с хранительницой энергии Веланией в Западном святилище в Лесах Вечной Песни.', },
  },
  [9120] = {
    'Падение Кел\'Тузада',
    {'От повелителя Наксрамаса остался лишь этот талисман. Голос рассудка подсказывает, что следует уничтожить его, дабы Король Мертвых не смог более возродиться. К счастью, вы не привыкли слушаться внутреннего голоса.|n|nКое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман. Кому есть дело до возрождения Кел\'Тузада?', },
    {'Отнесите талисман Кел\'Тузада в Часовню Последней Надежды в Восточных Чумных землях.', },
  },
  [9121] = {
    'Цитадель ужаса – Наксрамас',
    {'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.|n|nМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку тебе не хватает преданности делу Серебряного Рассвета, за чары придется немало заплатить. Ты можешь отказаться от задания и вернуться ко мне, как только тебя начнут почитать или превозносить. Тогда я сделаю тебе скидку.', },
    {'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 5 чародейских кристаллов, 2 кристалла-источника, 1 сферу Праведности и 60 золотых. Вы должны заслужить уважительное отношение Серебряного Рассвета.', },
  },
  [9122] = {
    'Цитадель ужаса – Наксрамас',
    {'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.|n|nМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку ты весьма $Gпредан:предана; делу Серебряного Рассвета, часть издержек мы возьмем на себя.', },
    {'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 2 чародейских кристалла, 1 кристалл-источник и 30 золотых. Вы должны заслужить почтительное отношение Серебряного Рассвета.', },
  },
  [9123] = {
    'Цитадель ужаса – Наксрамас',
    {'В чаще Проклятого леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.|n|nМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.', },
    {'Верховный маг Анджела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Сначала добейтесь того, чтобы вас превозносили в Серебряном Рассвете.', },
  },
  [9124] = {
    'Доспехи расхитителя гробниц на дороге не валяются...',
    {'Хочешь получить такую побрякушку?|n|n*Леопольд помахивает значком Алого ордена.*|n|nМне пригодилась бы твоя помощь в одном деле, $N. Я создаю броню расхитителей гробниц для глупцов, желающих сунуть нос в Наксрамас. У меня нет недостатка в материалах, за исключением конечностей и панцирей некрорахнидов. Принеси мне их, и получишь значок. Имей в виду, интенданты готовы отдать за эти побрякушки много интересного.', },
    {'Принесите 30 конечностей и панцирей некрорахнидов Охотнику Леопольду в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9125] = {
    'Конечности и панцири некрорахнидов',
    nil,
    nil,
  },
  [9126] = {
    'Копи костяной косы',
    {'Для изготовления доспехов костяной косы, изобретенных доном Хулио, требуются обломки костей – чем больше, тем лучше. Хотя безумцы, регулярно отправляющиеся в Наксрамас, приносят мне довольно много, обломки костей Плети для меня никогда не лишние.|n|nНе желаешь ли помочь мне? Так ты изничтожишь подлых тварей плети и снабдишь меня материалом для доспехов.', },
    {'Принесите 30 обломков костей Рогану Убийце в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9127] = {
    'Обломки костей',
    nil,
    nil,
  },
  [9128] = {
    'Уравнение стихий',
    {'Приветствую тебя, $Gстранник:странница;! Не ищешь ли ты работу? Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов.|n|nСлушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести. Чем больше, тем лучше!|n|nСредоточия стихий можно найти у элементалей всех форм и размеров.', },
    {'Принесите 30 средоточий стихий верховному магу Анджеле Досантос в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9129] = {
    'Средоточие Стихий',
    nil,
    nil,
  },
  [9130] = {
    'Товары из Луносвета',
    {'Привет новобранцам! У нас тут плохо со снабжением, но эльфы крови обещали нам материальную помощь. Это и будет твоим первым заданием.|n|nБери накладную и неси повелителю небес Солнечному Крылу. Он снабдит тебя дальнейшими инструкциями, как добраться до Луносвета.', },
    {'Доставьте накладную интенданта Лимель повелителю небес Солнечному Крылу в Транквиллион.', },
  },
  [9131] = {
    'Броня неустрашимости',
    {'Ты когда-нибудь $Gвидел:видела; доспехи неустрашимости, |3-6($C)? Конечно нет, ты же еще совсем салага. Так вот, послушай знатока – он великолепен!|n|nТы, наверное, недоумеваешь, какое это к тебе может иметь отношение? Вот что, недотепа, мне нужны пластины черного железа – как можно больше.|n|nС их помощью я скрепляю части доспехов неустрашимости для наших славных воинов. Так что я хорошо заплачу.', },
    {'Принесите 30 пластин черного железа Корфаксу в Часовню Последней Надежды в Восточных Чумных землях.', },
  },
  [9132] = {
    'Пластины из темного железа',
    nil,
    nil,
  },
  [9133] = {
    'Полет в Луносвет',
    {'$C, за весьма скромную плату я могу быстро доставить вас по воздуху на одном из этих великолепных животных! Смею вас заверить, это куда безопаснее, чем идти пешком!|n|nДобравшись до Луносвета, разыщи Сатрена Лазурного Рассвета на Базаре.|n|nКогда будешь $Gготов:готова; покорить небеса, обращайся.', },
    {'Оплатите полет в Луносвет и доставьте накладную от интенданта Лимель Сатрену Лазурному Рассвету в Луносвет.', },
  },
  [9134] = {
    'Повелительница небес Полудымка',
    {'Непохоже, чтобы у тебя была повозка или вьючное животное, так что лучше дам тебе тот груз, который ты сможешь унести. Если ты уже $Gговорил:говорила; с повелителем небес Солнечным Крылом в Транквиллионе, то тебе надо будет доставить вот этот ящичек интенданту Лимель как можно скорее, вернувшись назад по воздуху.|n|nДоставь этот товар на экспертизу повелительнице небес Полудымке к вратам Пастыря на входе в Луносвет.', },
    {'Доставьте товар интенданта Лимель повелительнице небес Полудымке к вратам Пастыря, что ведут в Луносвет.', },
  },
  [9135] = {
    'Возвращение к интенданту Лимель',
    {'Значит, все сходится. Сдается, эти Отрекшиеся готовы драться за нас до конца, и мы в долгу перед ними, хотя на лицо они ужасные и гнилые внутри.|n|nЛадно, к делу. Ты уже $Gговорил:говорила; с повелителем небес Солнечным Крылом в Транквиллионе? Если так, то за небольшую плату ты легко и быстро вернешься назад.|n|nДай знать, как будешь $Gготов:готова;.', },
    {'Оплатите обратный полет в Транквиллион в Призрачных землях и доставьте товары интенданта Лимель интенданту Лимель в Транквиллион в Призрачных землях.', },
  },
  [9136] = {
    'Дикая флора',
    {'Я изготавливаю особые доспехи для наших бравых солдат, входящих в Наксрамас – они называются доспехами сновидца. Обычно у меня нет недостатка в материалах, за исключением диких ростков.|n|nВозможно, ты подумаешь, что эта работа не серьезна, однако без диких ростков создание таких доспехов невозможно.|n|nИ я готова платить за эту работу знаками Рассвета или Марша!', },
    {'Принесите 30 диких ростков Райн в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9137] = {
    'Дикая флора',
    nil,
    nil,
  },
  [9138] = {
    'Деревня Солнечной Короны',
    {'Мы тут в окружении, |3-6($C). Все окрестные селения захвачены Плетью!|n|nСпеши на северо-восток к деревне Солнечной Короны и сокруши нерубов – тварей Плети! Их трудно с кем-либо спутать – они похожи на пауков.|n|nНе трать времени... Кель\'Талас должен снова стать нашим!', },
    {'Убейте 10 нерубов-стражей и возвращайтесь к чародею Вандрилу в Транкивиллион в Призрачные земли.', },
  },
  [9139] = {
    'Деревня Золотистой Дымки',
    {'Кое в чем мы преуспели, но есть еще два поселения, которые надо отбить!|n|nСледующая наша цель – Деревня Золотистой Дымки. Она находится к северо-западу отсюда, ее захватили призраки высших эльфов, что прежде обитали здесь. Я понимаю, что это ужасно, но их тактика почти та же, что и у Плети.|n|nИди и перебей этих призраков и духов, |3-6($C). Чтобы добраться туда, иди по западной дороге от Транквиллиона.', },
    {'Уничтожьте 6 кель\'дорайских привидений и 4 кель\'дорайских призрака в деревне Золотой Дымки, затем возвращайтесь к чародею Вандрилу в Транквиллион в Призрачных землях.', },
  },
  [9140] = {
    'Деревня Ветрокрылых',
    {'$N, тебе пришло время вступить в главную битву за поселения Призрачных земель. Деревня Ветрокрылых к юго-западу отсюда захвачена крупным и сильным ударным отрядом – тенями и горгульями. Ты выступишь на острие нашей атаки и ослабишь противника насколько возможно!|n|nМагистры соседнего святилища Солнца на сей раз сделали специальный запрос: они хотят, чтобы останки этих тварей Плети были доставлены им для изучения, дабы найти метод борьбы с ними.|n|nДоброй охоты!', },
    {'Соберите 6 порций иллюзорного вещества и 4 обломка горгульи. Возвращайтесь к чародею Вандрилу в Транквиллион в Призрачных землях.', },
  },
  [9141] = {
    'Не все так просто',
    {'Хочешь получить задание? Не все так просто. Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!|n|nХочешь получить задание – докажи, что ты его $Gдостоин:достойна;! Принеси мне знак доблести, тогда и поговорим.|n|nИмей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!', },
    {'Принесите знак доблести Серебряного Рассвета командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9142] = {
    'Задание мастера',
    nil,
    nil,
  },
  [9143] = {
    'Неприятности в Зеб\'Соре',
    {'Лейтенант бросил нас в атаку на троллей, что за озером, не разведав прежде обстановку. Из-за его тупости нас чуть под корень не вырезали! Слышишь меня, Томатрен? Ты идиот!|n|nНе поможешь ли нам, |3-6($C)? Этим троллям надо как следует всыпать! Мне придется остаться здесь и присматривать за лейтенантом – у него, похоже, совсем крыша поехала.|n|nИди прямо на восток, на другую сторону озера, в Зеб\'Сору. Я жажду крови! Принеси мне тролличьих ушей, я из них себе ожерелье сделаю!', },
    {'Добудьте 6 ушей троллей Зеб\'Соры и принесите их следопыту Валанне в Призрачные земли.', },
  },
  [9144] = {
    'Пропавший в Призрачных землях',
    {'Несколько дней назад моего племянника послали в Призрачные земли. Он ничего не говорил о своем задании, упомянул только, что оно секретное.|n|nОн до сих пор не вернулся. $N, я опасаюсь худшего! Возможно, черствым магистрам Луносвета и нет дела до пропавшего гонца, но для меня он как сын! Прошу тебя, $N, найди его, пожалуйста...', },
    {'Идите по дороге, ведущей из деревни Легкий Ветерок на юг, и найдите курьера Рассветного Странника.', },
  },
  [9145] = {
    'Спасти следопыта Валанну!',
    {'$C, я не могу здесь сидеть сложа руки и ждать аудиенции у верховного палача или госпожи Златилен! Дело не терпит отлагательств!|n|nМы бились с троллями Призрачной Сосны из Зеб\'Соры с северо-восточного берега озера Элрендар! Но лейтенант неудачно провел атаку, и мы потеряли многих Странников. А потом он просто спятил! Следопыт Валанна послала меня сюда, а следопыта Салиссу – в Анклав Странников за помощью.|n|nПрошу тебя, найди их, |3-6($C). Валанна тяжело ранена, а от лейтенанта толку никакого.', },
    {'Найдите следопыта Валанну и лейтенанта Томатрена на берегу озера Эрлендар в Призрачных землях близ деревни Солнечной Короны.', },
  },
  [9146] = {
    'Донесение капитану Гелиосу',
    {'Я попрошу тебя еще об одной, последней услуге, |3-6($C). На случай, если следопыт Салисса не доберется до Анклава Странников на южной оконечности озера, ступай туда и приведи подмогу.|n|nСвяжись с капитаном Гелиосом и скажи ему, что здесь случилось. Он наверняка пришлет подмогу, как только сможет.', },
    {'Поговорите с капитаном Гелиосом в Анклаве Странников на южном берегу озера Элрендар в Призрачных землях.', },
  },
  [9147] = {
    'Умирающий курьер',
    {'Ну, что без дела стоишь? Не видишь – мальцу нужна срочная помощь! Похоже, его тело сжигает чума. Еще пара минут – и даже такая мастерица-аптекарша, как я, уже ничем ему не поможет.|n|nЖивотные к югу от реки несут заразу в своей крови. Ступай-ка через мост и истреби больных животных. Принеси мне побольше образцов зараженной крови, и я сумею выделить сыворотку, способную спасти этого эльфа. Торопись!', },
    {'Аптекарь Тедра из Леса Вечной Песни просит вас принести ей 4 образца зараженной крови животных из Призрачных земель.', },
  },
  [9148] = {
    'Посылка в Транкивиллион',
    {'Нет сил... продолжать... при мне письмо... от лорда-регента Терона... там ужасное предостережение. Тебе придется доставить его вместо меня.|n|nОтнеси его чародею Вандрилу в Транквиллион. Этот город находится дальше к югу по этой дороге. Отправляйся туда... найди Вандрила...', },
    {'Отнесите письмо из Луносвета чародею Вандрилу в Транквиллон в Призрачных землях.', },
  },
  [9149] = {
    'Чумной берег',
    {'Чтобы найти лекарство от этой болезни, нам нужно понять, как она влияет на различные существа – от самых сложных форм жизни до простейших. |n|nЯ прибыл сюда для исследования мурлоков, поскольку они, как и мы, сохраняют свободу воли даже после смерти. Что делает этих ничтожных ублюдков такими особенными? Мне надо это выяснить, $N!|n|nОтправляйся на северо-запад и принеси мне их хребты, чтобы я мог изучить накопление заразы в их костном мозге. Кто знает, что за секрет хранят их жалкие кости?', },
    {'Принесите 6 хребтов чумных мурлоков аптекарю Рензитену в Транквиллион, что в Призрачных землях.', },
  },
  [9150] = {
    'Спасение прошлого',
    {'Прямо не верится! На юго-востоке от нас существует и действует настоящее магическое святилище – святилище Солнца! Все самые знаменитые магистры собрались туда ради этого!|n|nИ, конечно, все позабыли о святилище Луны. От него мало что осталось, и его сила породила странных тварей. |n|nНо я не дам добру пропасть. Отправляйся в святилище Луны и посмотри, нельзя ли собрать с тамошних тварей немного кристаллизованной субстанции?', },
    {'Магистр Даренис хочет, чтобы вы отправились в святилище Луны к западу от Транквиллиона и добыли 8 кристализованных субстанций маны с волшебных пожирателей и маначервей, что населяют это место.', },
  },
  [9151] = {
    'Святилище Солнца',
    {'Ты $Gдоказал:доказала; свою верность Транквиллиону, оказав содействие в борьбе против сил Плети. Из Луносвета прибыли несколько наших самых могучих магистров, чтобы перенести битву прямо на вражеский порог.|n|nОни восстановили чародейское святилище на юге и оттеснили Плеть из окрестностей. Они намерены нанести удар по Смертхольму, оплоту Дар\'Кхана. Тебе следует присоединиться к ним, $N. Уверен, $Gтакой закаленный:такая закаленная:c; |3-6($C), как ты, очень им пригодится.', },
    {'Поговорите с магистром Идонисом в святилище Солнца в Призрачных землях.', },
  },
  [9152] = {
    'Припасы могильщика',
    {'И как прикажете мне обеспечивать военные поставки, когда я даже своих собственных получить не могу? Мне обещали конвой – а он так и не прибыл. Кроме того, одну повозку пришлось бросить на западе, когда на меня напала шайка вурдалаков!|n|nС твоей помощью я мог бы заново открыть дело. Отправляйся из города по западной дороге мимо кладбища. По другую сторону Тропы Мертвых дорога раздваивается. Холм, за которым должна быть моя повозка, как раз за развилкой.', },
    {'Найдите припасы Ратиса Могильщика и верните их хозяину в Транквиллион в Призрачных землях.', },
  },
  [9153] = {
    'Под тенью',
    {'Парящие некрополи Плети не щадят ни Орду, ни Альянс. Тень летающих крепостей пала на Танарис, Выжженные Земли, Зимние Ключи и Пылающие степи.|n|nТолько объединив усилия, мы сможем противостоять этой беде.|n|nНекрополи поддерживаются энергией магических кругов, которые размещены в различных точках захваченных регионов. Все магические круги охраняются полчищами нежити. Мы определили, что если уничтожить эти толпы нежити, то защита кругов будет снята.', },
    {'Найдите по карте регион, атакуемый Плетью. Отправляйтесь туда и излейте свою ярость на некрополь, разгромив толпы Плети вокруг него. Доставьте 10 некротических рун Плети командиру Томасу Элерану в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9154] = {
    'Часовня Последней Надежды',
    {'Захватчики Плети вернулись, и их теперь куда больше, чем когда-либо прежде. Серебряный Рассвет собирает всех, кто может носить оружие и желает пустить его в ход, для защиты наших земель.|n|nЕсли разделяешь эти убеждения, отнеси этот документ Хранителю свитков в Часовню Последней Надежды в Восточных Чумных землях.', },
    {'Отнесите объявление о мобилизации Хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9155] = {
    'По Тропе Мертвых',
    {'Раз уж ты $Gзабрел:забрела; в такую даль, то $Gдолжен:должна; знать о Тропе Мертвых. Даже теперь твари Плети бездумно следуют по выжженной полосе, что оставил за собой Артас по пути в Луносвет.|n|nПокажи, на что ты $Gспособен:способна;, прореди ряды Плети на Тропе. Если отработаешь свой хлеб, я замолвлю за тебя доброе слово.', },
    {'Убейте 10 восставших ненасытников и 10 уродливых каннибалов на Тропе Мертвых. Возвращайтесь к стражу смерти Ратиэлю в Транквиллион за наградой.', },
  },
  [9156] = {
    'Разыскиваются: Гнилоступ и Лузран',
    {'Сим назначается щедрая награда за мерзостных поганищ, известных как Гнилоступ и Лузран! Эти отвратительные создания Дар\'Кхана чрезвычайно опасны. Их видели близ Воющего и Кровоточащего зиккуратов. Тот, кто желает получить награду, должен предоставить головы этих поганищ стражу смерти Ратиэлю в доказательство своей победы!', },
    {'Найдите в Призрачных землях Гнилоступа и Лузрана. Принесите их головы стражу смерти Ратиэлю в Транквиллион и получите награду.', },
  },
  [9157] = {
    'Забытые обряды',
    {'Каждый год мы, обитатели деревни Солнечной короны, принимали участие в обряде, который был предназначен для того, чтобы держать под контролем различные аспекты природы. Власть над стихией Воды символизировалась призыванием и покорением элементаля по имени Аквантион. Но наши чары были подлым образом искажены, в результате этот поганец разорвал узы и сам поработил нас!|n|nВо время обряда мы носили медальоны в виде волны. Найди их на дне этого озера, они нужны нам, чтобы освободить души наших сородичей!', },
    {'Принесите 8 медальонов Волны Геранису Белому Рассвету в Призрачные земли.', },
  },
  [9158] = {
    'Разносчики заразы',
    {'Ты $Gпроявил:проявила; мужество, отправившись сюда, в Призрачные земли, $N. Здесь у нас много работы и мало храбрецов, готовых за нее взяться.|n|nЕсли ты действительно $Gготов:готова; нам помочь, я осмелюсь предложить тебе одно неблагодарное задание. Вся дикая природа здесь поражена заразой, и мы должны остановить ее распространение. Ступай охотиться на светлопалых рысей к востоку и югу отсюда и возвращайся, когда перебьешь достаточное их число.', },
    {'Странница Седайна из Анклава Странников в Призрачных землях хочет, чтобы вы убили 10 светлопалых рысей.', },
  },
  [9159] = {
    'Обуздание заразы',
    {'Ты $Gпоказал:показала; себя достойным союзником, $N. Я прошу тебя продолжить труды и выследить еще некоторое количество зараженных животных. На сей раз придется иметь дело с более опасными тварями. А именно – с воронковыми пауками-прядильщиками к западу от Тропы Мертвых и мрачницами-вампирами к югу отсюда. Покончишь с делом – возвращайся ко мне.', },
    {'Странница Седайна из Анклава Странников Призрачных Земель хочет, чтобы вы убили 8 воронковых пауков-прядильщиков и 10 мрачниц-вампиров.', },
  },
  [9160] = {
    'Обследуйте район Ан\'дарота',
    {'$C, у нас проблемы с группой ночных эльфов, недавно захвативших находящийся поблизости островок. Они устроили небольшой лагерь в Ан\'дароте, древнем узле линии магической силы, облюбованном еще высшими эльфами. Это к северо-западу отсюда. Туда ведет грунтовая дорога, что начинается сразу за Тропой Мертвых.|n|nПомоги нам – отправляйся туда, узнай, что они затевают, и перебей сколько сможешь этих надменных ночных эльфов.', },
    {'Обследуйте район Ан\'дарота, убейте 12 часовых-шпионов и возвращайтесь к госпоже Златилен в Транквиллион в Призрачных землях.', },
  },
  [9161] = {
    'Тень предателя',
    {'Говорят, что Дар\'Кхан Дратир восстал из мертвых, чтобы возглавить полчища Плети здесь, в Призрачных землях. Дар\'Кхан давно уже связался с Плетью... но некогда, при жизни, он был эльфом... Большую часть своего времени он проводил в Башне Утренней Звезды, к северо-востоку отсюда. Он скрывался там долгими ночами, строя козни против собственного народа. |n|nОбыщи башню, $N, может, найдешь еще какую информацию. Возможно, он вел дневник или делал записи. Поищи, информация лишней не бывает.', },
    {'Отправляйтесь к Башне Утренней Звезды в Призрачных землях и найдите любую информацию о прошлом Дар\'Кхана.', },
  },
  [9162] = {
    'Отблески былого',
    {'Просматривая страницы дневника, вы вдруг испытываете острое ощущение того, что за вами наблюдают.|n|nСодержание дневника пугает. Душа Дар\'Кхана полна ненависти и презрения к собственному народу. Все его махинации и интриги изложены здесь в мельчайших подробностях.|n|nВозможно, Винне может пригодиться эта информация.', },
    {'Вернитесь к следопыту Винне в Анклав Странников Призрачных земель и отдайте ей дневник Дар\'Кхана.', },
  },
  [9163] = {
    'Вылазка на оккупированную территорию',
    {'Наиболее простой способ выведать планы ночных эльфов – отправить тебя на их остров с целью добыть любую доступную информацию.|n|nЯ хочу, чтобы ты $Gнаправился:направилась; на запад по дороге из города на остров Шаландис, что прямо рядом с побережьем. Ступай туда и принеси мне все планы, которые найдешь на острове либо на корабле.', },
    {'Выкрадите планы ночных эльфов: Ан\'дарот, Ан\'овин и Магическое наблюдение за син\'дорай, затем доставьте их госпоже Златилен в Транквиллион в Призрачных землях.', },
  },
  [9164] = {
    'Пленники Смертхольма',
    {'А, да. Одно их моих лучших изобретений. Этот напиток снимает большинство алхимически вызванных видов оцепенения.|n|nПобочные эффекты – головокружение, рвота и – в редких случаях – временная слепота. Но все лучше, чем то, что Плеть готовит для этих пленников в Смертхольме, скажу я тебе.|n|nУдачи и еще раз удачи, $Gотважный:отважная:c; |3-6($C). Она тебе пригодится.', },
    {'Возьмите приводящее в сознание зелье Рензитена с собой в Смертхольм и спасите ученика Варниса, аптекаря Инит и следопыта Ведорана. Возвращайтесь к чародейке Джанеде в Святилище Солнца за наградой.', },
  },
  [9165] = {
    'Подорожная',
    {'Если бы не помощь странников вроде тебя, наш караван никогда не добрался бы до пункта назначения! Твари Плети лезут из всех щелей!|n|n*Страж Дидье утирает лоб*|n|nТеперь надо дождаться здесь фельдмаршала Чамберса, чтобы он подписал тебе подорожную. Предъявишь ее командиру Метцу в Часовню Последней Надежды в Восточные Проклятые земли.|n|nИ вот что, $N, имей в виду, Метц из тех парней, которые любят орать, мол, прихлопну как муху да кишки по деревьям развешу... Только в отличие от большинства подобных крикунов, именно так он и сделает.', },
    {'Доставьте подписанную подорожную командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.', },
  },
  [9166] = {
    'Донесение в Ан\'телас',
    {'Отправляйся на восток. На южном склоне пика Солнечного Пастбища, к северо-востоку от святилища Солнца, находится Ан\'телас. Именно туда следует доставить обнаруженные нами планы ночных эльфов.|n|nМагистр Силастор постоянно проводит там исследования узлов линий силы для потенциального их использования в битве с Плетью. Пусть глянет на эти планы и прольет свет на замыслы ночных эльфов.', },
    {'Передайте планы ночных эльфов магистру Силастору из Ан\'теласа в Призрачных землях.', },
  },
  [9167] = {
    'Гибель предателя',
    {'Все, что мы сделали в Призрачных землях, призвано вернуть принадлежащее нам по праву. Плеть слишком долго держала в своих когтях эти земли.|n|nПришло время расплаты, $N. Благодаря тебе и нашим новым союзникам, Отрекшимся, час отмщения близок.|n|nТот, кто хочет похитить мощь Солнечного Колодца, должен сгинуть! Ступай в Смертхольм, оплот Плети к югу от Тропы Мертвых. Принеси мне голову Дар\'Кхана, и твои деяния не будут забыты!', },
    {'Убейте Дар\'Кхана Дратира в Смертхольме и принесите его голову магистру Каендрису в Святилище Солнца в Призрачных землях.', },
  },
  [9168] = {
    'Сердце Смертхольма',
    {'Глубоко в недрах Смертхольма наши враги пытаются создать более сильных и смертоносных призрачных солдат. Эти гнусные твари – совершенные инструменты, созданные самим Дар\'Кханом и закаленные черной магией Смертхольма.|n|nОтправляйся в башню Проклятых Смертхольма и уничтожь их, $N. Мы не можем позволить армии нашего врага усиливаться в то время, как мы с трудом удерживаем плацдарм в Призрачных землях.', },
    {'Уничтожьте 8 очей Дар\'Кхана и доложите об этом магистру Идонису из святилища Солнца в Призрачных землях.', },
  },
  [9169] = {
    'Ан\'овин: отключение',
    {'Эти лунные кристаллы – наблюдательные устройства, и следят они за нами! Я понимаю, что из Ан\'дарота до кристаллов дотянуться не смогут, чего не могу сказать про Ан\'овин, что лежит прямо к югу отсюда.|n|nИз схем, которые теперь есть в моем распоряжении, я узнал основные принципы действия лунных кристаллов; достаточно просто отключить их. Отправляйся в Ан\'овин, добудь сферу управления у одного из ночных эльфов и с ее помощью отключи лунный кристалл, чтобы не дать осуществиться их планам!|n|nТоропись, |3-6($C)!', },
    {'Добудьте сферу управления кристаллом и с ее помощью отключите лунный кристалл ночных эльфов в Ан\'овине. Затем возвращайтесь к магистру Силастору в Ан\'телас в Призрачных землях.', },
  },
  [9170] = {
    'Приспешники Дар\'Кхана',
    {'Этот подлый предатель, Дар\'Кхан, обрел великую власть, встав на сторону Плети. Его приспешники командуют огромной аримией нежити, что противостоит нашим тающим силам.|n|nМасофет Черный, Джурион Обманщик, Боргот Кровопускатель и Мирдоран Мерзостный. Запомни эти имена крепко, ибо в Призрачных землях эти полководцы Плети уступают только самому Дар\'Кхану. Срази их, и их безмозглое воинство будет повергнуто в хаос.', },
    {'Магистр Идонис хочет, чтобы вы отправились в Смертхольм и сразили Масофета Черного, Джуриона Обманщика, Боргота Кровопускателя и Мирдорана Мерзостного. Выполнив поручение, отчитайтесь перед магистром Идонисом в святилище Солнца Призрачных земель.', },
  },
  [9171] = {
    'Хрустящий деликатес',
    {'Это невыносимо! Мне тут совершенно не из чего готовить! Госпожа направила меня в Луносвет – ей нужны утонченные блюда, соответствующие ее положению. А что, нет? И вот я здесь, но тут нечего есть! Ты $Gдолжен:должна; пойти и принести свежей дичи, чтобы я хоть что-нибудь смог приготовить.|n|nГоспожа Златилен любит покушать что-нибудь хрустящее. К юго-западу отсюда, по ту сторону Тропы Мертвых, полно воронковых пауков-прядильщиков. Да, они противные, я знаю, но именно они нам и нужны.', },
    {'Добудьте 5 хрустящих паучьих лапок и принесите их главному шеф-повару Плеснеру в Транквиллион в Призрачных землях.', },
  },
  [9172] = {
    'Доклад магистру Каендрису',
    {'Магистры святилища Солнца далеко продвинулись в анализе слабостей Плети при помощи Отрекшихся. Магистр Каендрис знает, что делать с этой информацией.|n|nСвятилище Солнца находится к юго-западу отсюда. Торопись, $N. Дар\'Кхан – коварный враг, он следит за каждым нашим шагом!', },
    {'Принесите дневник Дар\'Кхана магистру Каендрису в святилище Солнца в Призрачных землях.', },
  },
  [9173] = {
    'Захват Шпилей Ветрокрылых',
    {'$C, я желаю, чтобы ты $Gзахватил:захватила; Шпили Ветрокрылых!|n|nЭто высокая честь. Шпили Ветрокрылых – родина Сильваны Ветрокрылой, повелительницы Отрекшихся и бывшего главнокомандующего следопытов эльфов. Однако ныне башня захвачена безмозглыми полчищами Плети.|n|nЧтобы добраться туда, ступай по южной дороге до развилки. Возьми направо и, пересекши Тропу Мертвых, иди на юго-запад. Ты обязательно увидишь ее.', },
    {'Убейте 8 послушников из Смертхольма и 10 павших следопытов, затем возвращайтесь к верховному палачу Маврену в Транквиллион в Призрачных землях.', },
  },
  [9174] = {
    'Победа над Аквантионом',
    {'Этот злобный элементаль сгубил много жизней в тот роковой день, когда восстал против нас. Чтобы нарушить наш обряд, он призвал подлых мурлоков. Более того, ему удалось исказить наши чары и обратить их против нас.|n|nПокажи ему всю силу нашей неутоленной мести! Возьми эти медальоны и возложи их на алтарь Укрощения Приливов на дне озера. Аквантион тут же ответит на твой вызов!|n|nНо берегись, |3-6($R)! Поскольку наша магия более не властна над ним, гнев его будет неукротим! Срази Аквантиона, дабы мы обрели покой!', },
    {'Геранис Белый Рассвет хочет, чтобы вы нырнули на дно озера к востоку от деревни Солнечной Короны и возложили связку медальонов на алтарь Укрощения Приливов. Призовите и сразите элементаля по имени Аквантион, затем возвращайтесь к Геранису.', },
  },
  [9175] = {
    'Ожерелье Госпожи',
    {'Ожерелье мерцает, это настоящий шедевр ювелирного искусства, который светится даже во мраке, окутывающем Призрачные земли. Судя по надписи и месту, где вы его нашли, это наверняка принадлежит самой Леди Сильване Ветрокрылой!|n|nНаверное, лучше всего будет отнести эту вещь верховному палачу Маврену в Транквиллион. Похоже, он самый высокопоставленный Отрекшийся в здешних местах и наверняка знает, что с этой вещью делать.', },
    {'Отнесите ожерелье Госпожи верховному палачу Маврену в Транквиллион в Призрачных землях.', },
  },
  [9176] = {
    'Зиккураты-близнецы',
    {'Судя по этому дневнику, Дар\'Кхан пообещал Плети два могучих эльфийских артефакта: камень Света и камень Пламени. Они наполнены магический силой Солнечного Колодца и настроены так, чтобы Плеть не могла овладеть ими.|n|nЭти кристаллы предполагалось перенести туда, где ныне стоят Воющий и Кровоточащий зиккураты, прямо в центр Тропы Мертвых. Если они и доныне там, нам нужно вернуть их. Их сила очень понадобится нам в борьбе с врагом.', },
    {'Отправьтесь к Кровоточащему зиккурату и Воющему зиккурату и добудьте оттуда камень Света и камень Пламени. После этого возвращайтесь к магистр Каендрису в Святилище Солнца.', },
  },
  [9177] = {
    'Путь в Подгород',
    {'Невероятно! Похоже, это подарок Сильване Ветрокрылой от ее сестры Аллерии!|n|nТебе необходимо тотчас же доставить эту вещь ей в Подгород! Двор госпожи находится в Королевском квартале.|n|nЧтобы попасть туда, воспользуйся шаром транслокации во Внутреннем святилище Дворца Ярости Солнца в городе Луносвет, который перенесет тебя в Подгород. Как только окажешься там, спустись на подъемнике в сам город. Чтобы попасть в Королевский квартал, воспользуйся своими картами.', },
    {'Отнесите Сильване Ветрокрылой ожерелье Госпожи в Королевский квартал Подгорода.', },
  },
  [9178] = {
    'Задание мастера: массивное грузило',
